-- ------------------------------------------------------
-- DỮ LIỆU BẢNG: 6. SẢN PHẨM (PRODUCTS)
-- ------------------------------------------------------
LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,'Hũ Kem Dưỡng Ẩm Chuyên Sâu Cho Da Khô Cetaphil Moisturizing Cream',5,3,'Hũ kem dưỡng ẩm Cetaphil Moisturizing Cream với công thức giàu dưỡng chất chứa dầu hạnh nhân và Vitamin E, giúp khóa ẩm tức thì và duy trì độ ẩm suốt 48 giờ cho làn da khô đến rất khô và da nhạy cảm.','[\"Dưỡng ẩm chuyên sâu và duy trì màng ẩm tự nhiên suốt 48 giờ\", \"Làm dịu tức thì tình trạng ngứa rát, nứt nẻ và khô căng khó chịu\", \"Phục hồi hoàn toàn hàng rào bảo vệ da chỉ sau 1 tuần sử dụng\"]','[\"Glycerin\", \"Niacinamide (Vitamin B3)\", \"Panthenol (Pro-Vitamin B5)\", \"Dầu hạnh nhân ngọt (Sweet Almond Oil)\"]','Thoa đều kem lên vùng da mặt hoặc toàn thân hàng ngày sau khi tắm hoặc bất cứ khi nào da có dấu hiệu khô căng.','cham-soc-toc-ca-nhan/cetaphil/duong-am/hu-kem-duong-am-cetaphil-soothing-moisturizing-cream-2.jpg'),(2,'Kem Dưỡng Ẩm Làm Dịu Da Cho Bé Cetaphil Baby Soothing Moisturizing Cream',5,3,'Kem dưỡng ẩm Cetaphil Baby Soothing Moisturizing Cream nhẹ dịu chuyên biệt cho làn da mỏng manh của trẻ sơ sinh và trẻ nhỏ, chứa bơ hạt mỡ và vitamin giúp bảo vệ da bé khỏi chàm sữa và hăm tã.','[\"Dưỡng ẩm và làm mềm làn da nhạy cảm non nớt của bé\", \"Ngăn ngừa và làm dịu hiện tượng nứt nẻ, chàm sữa và mẩn đỏ\", \"Không chứa paraben, không hương liệu, độ pH cân bằng dịu nhẹ\"]','[\"Bơ hạt mỡ hữu cơ (Shea Butter)\", \"Glycerin\", \"Dầu đậu nành\", \"Vitamin E\"]','Lấy lượng kem vừa đủ mát-xa nhẹ nhàng lên mặt và cơ thể bé sau khi tắm hoặc trước khi đi ngủ.','cham-soc-toc-ca-nhan/cetaphil/duong-am/kem-duong-am-cetaphil-baby-soothing-moisturizing-cream.jpg'),(3,'Tuýp Kem Dưỡng Ẩm Cetaphil Moisturizing Cream Tiện Lợi',5,3,'Dạng tuýp nhỏ gọn của dòng kem dưỡng ẩm Cetaphil Moisturizing Cream trứ danh, thuận tiện mang theo khi đi làm, du lịch để cấp ẩm tức thì cho da khô và nhạy cảm.','[\"Cấp ẩm sâu, thẩm thấu nhanh không gây bết dính\", \"Bảo vệ da chống lại 5 dấu hiệu nhạy cảm: khô, căng, ngứa, rát, màng ẩm suy yếu\", \"Thiết kế dạng tuýp sạch sẽ, tiện lợi mang theo bên mình\"]','[\"Niacinamide\", \"Panthenol\", \"Glycerin\", \"Tocopherol (Vitamin E)\"]','Thoa trực tiếp lên da mặt, bàn tay, khuỷu tay hoặc bất kỳ vùng da khô nào cần phục hồi ẩm.','cham-soc-toc-ca-nhan/cetaphil/duong-am/tuyp-kem-duong-am-cetaphil-soothing-moisturizing-cream.jpg'),(4,'Sữa Rửa Mặt Dịu Nhẹ Cho Da Nhạy Cảm Cetaphil Gentle Skin Cleanser',3,3,'Sữa rửa mặt Cetaphil Gentle Skin Cleanser là công thức làm sạch không xà phòng được bác sĩ da liễu khuyên dùng hàng đầu, nhẹ nhàng loại bỏ bụi bẩn mà vẫn bảo toàn độ ẩm tự nhiên của da.','[\"Làm sạch êm dịu, không gây căng rát hay bào mòn da\", \"Duy trì độ ẩm tự nhiên, củng cố hàng rào bảo vệ da\", \"Có thể dùng rửa mặt khô không cần nước hoặc rửa với nước\"]','[\"Niacinamide (Vitamin B3)\", \"Panthenol (Pro-Vitamin B5)\", \"Glycerin cấp ẩm\"]','Thoa sữa rửa mặt lên da, mát-xa nhẹ nhàng sau đó rửa sạch lại với nước (hoặc dùng khăn mềm lau sạch nếu rửa khô).','cham-soc-toc-ca-nhan/cetaphil/sua-rua-mat/sua-rua-mat-diu-nhe-cetaphil-gentle-skin-cleanser-1.jpg'),(5,'Sữa Tắm Gội Toàn Thân Chiết Xuất Hoa Cúc Cho Bé Cetaphil Baby Wash & Shampoo',13,3,'Sữa tắm gội 2 trong 1 Cetaphil Baby Wash & Shampoo chứa chiết xuất hoa cúc hữu cơ Calendula giúp nhẹ nhàng làm sạch tóc và da toàn thân cho bé, mang lại cảm giác thơm mát mềm mại.','[\"Công thức không cay mắt dịu nhẹ tuyệt đối cho trẻ nhỏ\", \"Chiết xuất hoa cúc Calendula kháng khuẩn và làm dịu kích ứng da\", \"Cung cấp độ ẩm giúp tóc suôn mềm và da ẩm mượt\"]','[\"Chiết xuất hoa cúc hữu cơ (Organic Calendula)\", \"Panthenol\", \"Glycerin\"]','Cho một lượng vừa đủ ra tay hoặc bông tắm, tạo bọt nhẹ nhàng và tắm gội toàn thân cho bé, sau đó tráng lại bằng nước sạch.','cham-soc-toc-ca-nhan/cetaphil/sua-tam/sua-tam-goi-hoa-cuc-cetaphil-babywash.jpg'),(6,'Dầu Gội Dove Óng Mượt Vào Nếp Tự Nhiên Chiết Xuất Hoa Sen & Nước Gạo',15,6,'Dầu gội Dove Vào Nếp Tự Nhiên lấy cảm hứng từ bí quyết dưỡng tóc của phụ nữ Nhật Bản với chiết xuất hoa sen thanh nhã và nước gạo lên men, giúp mái tóc suôn mượt và vào nếp bồng bềnh suốt ngày dài.','[\"Giúp mái tóc vào nếp suôn mượt, không lo xơ rối\", \"Chiết xuất hoa sen thanh lọc tóc và lưu hương thơm tinh tế\", \"Nước gạo giàu khoáng chất nuôi dưỡng sợi tóc chắc khỏe từ gốc\"]','[\"Chiết xuất hoa sen Nhật Bản\", \"Nước gạo lên men\", \"Dưỡng chất Nutritive Serum\"]','Thoa đều dầu gội lên tóc ướt, xoa bóp nhẹ nhàng tạo bọt và xả sạch với nước. Dùng kết hợp dầu xả để đạt hiệu quả tốt nhất.','cham-soc-toc-ca-nhan/dove/dau-goi/dau-goi-chai-bu-dove-vao-nep-tu-nhien3.jpg'),(7,'Dầu Gội Dove Phục Hồi Tóc Chiết Xuất Matcha & Hoa Anh Đào',15,6,'Dầu gội Dove Matcha & Hoa Anh Đào thanh lọc da đầu và ngăn ngừa hư tổn, kết hợp trà xanh chống oxy hóa và hương thơm hoa anh đào ngọt ngào mang lại cảm giác sảng khoái.','[\"Thanh lọc bụi bẩn và dầu thừa tích tụ trên da đầu\", \"Bảo vệ tóc trước tác hại của ô nhiễm môi trường và nhiệt độ\", \"Hương thơm hoa anh đào nhẹ nhàng, ngọt ngào suốt 24h\"]','[\"Chiết xuất trà xanh Matcha Nhật Bản\", \"Hương hoa anh đào (Cherry Blossom)\", \"Hệ dưỡng chất Bio-Nourish\"]','Làm ướt tóc, lấy lượng dầu gội vừa đủ tạo bọt và mát-xa đều khắp da đầu, sau đó xả sạch lại bằng nước.','cham-soc-toc-ca-nhan/dove/dau-goi/dau-goi-dove-matcha-hoa-anh-dao.jpg'),(8,'Dầu Gội Dove Ngăn Gãy Rụng Tóc Với Bio-Serum Chuyên Sâu',15,6,'Dầu gội Dove Ngăn Rụng Tóc chứa hoạt chất Bio-Cellular Complex thấm sâu vào từng sợi tóc, củng cố cấu trúc tóc từ gốc đến ngọn giúp giảm gãy rụng tới 98%.','[\"Giảm thiểu gãy rụng tóc hiệu quả rõ rệt sau 2 tuần\", \"Nuôi dưỡng nang tóc chắc khỏe, giảm tình trạng đứt gãy sợi tóc\", \"Cung cấp độ ẩm mịn mượt, không làm bết rít da đầu\"]','[\"Bio-Cellular Complex\", \"Serum dưỡng sâu\", \"Sodium Gluconate\"]','Mát-xa nhẹ nhàng lên tóc ướt từ chân đến ngọn tóc rồi xả sạch với nước.','cham-soc-toc-ca-nhan/dove/dau-goi/dau-goi-dove-ngan-gay-rung-toc.jpg'),(9,'Dầu Gội Dove Phục Hồi Hư Tổn Intensive Repair',15,6,'Dầu gội Dove Intensive Repair dành riêng cho tóc uốn, nhuộm và hư tổn nặng, bổ sung Keratin Repair Actives giúp phục hồi bề mặt sợi tóc và nuôi dưỡng sâu lõi tóc.','[\"Phục hồi bề mặt sợi tóc khô xơ chẻ ngọn tức thì\", \"Bổ sung protein và keratin tái cấu trúc lõi tóc khỏe khoắn\", \"Mái tóc trở nên óng ả, mềm mượt dễ chải\"]','[\"Keratin Repair Actives\", \"Nutri-Keratin\", \"Glycerin dưỡng ẩm\"]','Làm ướt toàn bộ tóc, thoa dầu gội tạo bọt và xoa bóp kỹ phần đuôi tóc hư tổn trước khi xả sạch.','cham-soc-toc-ca-nhan/dove/dau-goi/dau-goi-dove-phuc-hoi-hu-ton.jpg'),(10,'Kem Dưỡng Ẩm Toàn Thân Nivea Care Intensive Pflege Chuyên Sâu',5,13,'Kem dưỡng ẩm Nivea Care Intensive Pflege với công nghệ Hydro Wax đột phá, tan đều trên da ngay sau khi thoa, cấp ẩm sâu suốt 24h mà hoàn toàn không để lại cảm giác nhờn dính.','[\"Cấp ẩm sâu suốt 24 giờ cho da mềm mại và mịn màng\", \"Kết cấu kem mịn tan nhanh, thấm ngay vào da không bết rít\", \"Phù hợp dùng cho cả da mặt và toàn bộ cơ thể\"]','[\"Hydro Wax dưỡng chất\", \"Glycerin\", \"Bơ hạt mỡ hữu cơ\"]','Lấy một lượng kem vừa đủ thoa đều khắp mặt hoặc cơ thể sau khi tắm.','cham-soc-toc-ca-nhan/nivea/kem-duong/kem-duong-am-care-intensive-pflege.jpg'),(11,'Kem Dưỡng Ẩm Huyền Thoại Nivea Creme Hộp Thiếc Cổ Điển',5,13,'Kem dưỡng ẩm Nivea Creme hộp thiếc xanh kinh điển của Đức chứa hoạt chất dưỡng ẩm Eucerit độc quyền, giải pháp cấp cứu hoàn hảo cho những vùng da nứt nẻ, thô ráp nhất.','[\"Dưỡng ẩm siêu đậm đặc bảo vệ da khỏi khô nẻ mùa đông\", \"Làm mềm nhanh các vùng da chai ráp như gót chân, khuỷu tay, đầu gối\", \"An toàn lành tính cho cả gia đình và trẻ em\"]','[\"Eucerit độc quyền Nivea\", \"Panthenol\", \"Glycerin\"]','Thoa trực tiếp lên da mặt, môi nứt nẻ hoặc các vùng da khô ráp trên cơ thể bất cứ khi nào cần.','cham-soc-toc-ca-nhan/nivea/kem-duong/kem-duong-am-nivea-creme-thiec.jpg'),(12,'Serum Dưỡng Thể Sáng Da Mờ Thâm Nivea Extra Bright 10 Super Vitamins & Skin Foods',13,13,'Serum dưỡng thể Nivea Extra Bright 10 Super Vitamins chứa 100x Vitamin A và phức hợp 10 loại siêu vitamin & dưỡng chất từ thiên nhiên, làm sáng da và mờ vết thâm sạm chỉ sau 7 ngày.','[\"Làm sáng đều màu da và mờ các đốm thâm sạm sau 7 ngày\", \"Tái tạo cấu trúc tế bào da khỏe mạnh từ 10 loại vitamin tự nhiên\", \"Kết cấu serum siêu nhẹ, thấm nhanh trong 3 giây\"]','[\"100x Vitamin A\", \"Vitamin C, E, B3, B9, Pro-B5\", \"Chiết xuất Goji Berry, Lựu, Bơ, Chanh vàng\"]','Thoa đều serum lên toàn thân mỗi ngày 2 lần vào buổi sáng và tối sau khi tắm.','cham-soc-toc-ca-nhan/nivea/serum-duong-the/serum-duong-the-nivea10super.jpg'),(13,'Sữa Dưỡng Thể Nivea Extra Bright C&E Vitamin Lotion Sáng Mịn Mướt Mát',13,13,'Sữa dưỡng thể Nivea Extra Bright C&E kết hợp sức mạnh nhân đôi của 50x Vitamin C tinh khiết và Vitamin E đậm đặc, vừa dưỡng trắng rạng ngời vừa dưỡng ẩm sâu cho làn da căng mọng.','[\"Dưỡng da sáng hồng bật tông rõ rệt sau 7 ngày\", \"Vitamin E khóa ẩm giữ da luôn mềm mại và căng tràn sức sống\", \"Bộ lọc tia UV bảo vệ da trước ánh nắng mặt trời\"]','[\"50x Vitamin C cô đặc\", \"Vitamin E tinh khiết\", \"Màng lọc UV\"]','Thoa sữa dưỡng thể đều đặn khắp người mỗi sáng và tối để có làn da sáng khỏe tự nhiên.','cham-soc-toc-ca-nhan/nivea/sua-duong-the/sua-duong-the-nivea-extra-bright-c-e.jpg'),(14,'Sữa Dưỡng Thể Ban Đêm Nivea Extra Bright Night Nourish Phục Hồi Chuyên Sâu',13,13,'Sữa dưỡng thể ban đêm Nivea Night Nourish tận dụng thời điểm vàng tái tạo da ban đêm, cung cấp hàm lượng collagen và Vitamin C giúp da phục hồi hư tổn và trắng sáng mịn màng.','[\"Thúc đẩy quá trình tái sinh tế bào da mới suốt đêm dài\", \"Bổ sung collagen phục hồi độ đàn hồi và săn chắc cho da\", \"Dưỡng ẩm sâu không gây dính mền gối khi ngủ\"]','[\"Q10 & Collagen\", \"Dẫn xuất Vitamin C nguyên chất\", \"Glycerin cấp ẩm\"]','Thoa đều lên toàn bộ cơ thể vào mỗi buổi tối trước khi đi ngủ.','cham-soc-toc-ca-nhan/nivea/sua-duong-the/sua-suong-the-nivea-extra-bright-night.jpg'),(15,'Dầu Gội Pantene Pro-V Moisture Renewal Dưỡng Ẩm Mềm Mượt',15,14,'Dầu gội Pantene Pro-V Daily Moisture Renewal bổ sung độ ẩm dồi dào cho mái tóc khô ráp, khóa ẩm từ gốc tới ngọn giúp tóc bóng mượt và chắc khỏe suốt 24h.','[\"Cấp ẩm chuyên sâu cho mái tóc khô xơ và thiếu sức sống\", \"Công thức Pro-V độc quyền phục hồi tóc chắc khỏe từ bên trong\", \"Bảo vệ tóc trước tác hại của nhiệt và bụi bẩn\"]','[\"Công thức Pro-Vitamin B5\", \"Chất dưỡng ẩm Moisture Renewal\", \"Chất chống oxy hóa Histidine\"]','Thoa dầu gội lên tóc ướt, tạo bọt nhẹ nhàng và xả sạch lại bằng nước sạch.','cham-soc-toc-ca-nhan/pantene/dau-goi/dau-goi-pantene-pro-v-moistrue.jpg'),(16,'Dầu Gội Pantene Pro-V Hair Fall Control Ngăn Rụng Tóc Hiệu Quả',15,14,'Dầu gội Pantene Hair Fall Control tăng cường dưỡng chất Pro-V nuôi dưỡng sợi tóc từ sâu bên trong, giúp giảm rụng tóc do đứt gãy tới 98% cho mái tóc dày dặn bồng bềnh.','[\"Giảm đáng kể tình trạng gãy rụng tóc sau 14 ngày\", \"Tăng cường độ đàn hồi và dẻo dai của từng sợi tóc\", \"Làm sạch dịu nhẹ da đầu, giữ tóc bồng bềnh lâu bết\"]','[\"Pro-Vitamin B5 Complex\", \"Dưỡng chất Keratin Damage Blockers\"]','Làm ướt tóc, mát-xa tạo bọt từ chân tóc đến ngọn tóc rồi xả sạch.','cham-soc-toc-ca-nhan/pantene/dau-goi/dau-goi-pantene-pro-v-vitamin-ngan-rung-toc.jpg'),(17,'Dầu Gội Pantene Sạch Gàu & Mượt Tóc Anti-Dandruff',15,14,'Dầu gội Pantene Anti-Dandruff kết hợp hoạt chất trị gàu ZPT và công thức Pro-V dưỡng tóc, vừa đánh bay gàu ngứa vừa nuôi dưỡng mái tóc suôn mượt không khô xơ.','[\"Đánh bay vảy gàu và ngăn ngừa gàu quay trở lại\", \"Làm dịu cơn ngứa da đầu tức thì\", \"Không làm khô đuôi tóc như các loại dầu gội trị gàu thông thường\"]','[\"Kẽm Pyrithione (ZPT)\", \"Công thức Pro-V\", \"Tinh dầu làm mềm tóc\"]','Làm ướt tóc, mát-xa đều trên da đầu trong 2 phút để hoạt chất trị gàu phát huy tối đa tác dụng rồi xả sạch.','cham-soc-toc-ca-nhan/pantene/dau-goi/dau-goi-pantene-sach-gau-anti-drandruff.jpg'),(18,'Hũ Kem Ủ Serum Tóc Cao Cấp Pantene Miracles Daily Moisture Treatment',15,14,'Hũ kem ủ tóc Pantene Miracles dòng cao cấp chứa viên nang serum dưỡng chất vàng tan chảy, thẩm thấu trực tiếp vào lõi tóc giúp hồi sinh mái tóc hư tổn nặng chỉ sau một lần ủ.','[\"Viên nang dưỡng chất serum vàng tan chảy nuôi dưỡng sâu từng sợi tóc\", \"Hồi sinh tức thì mái tóc xơ rối, cháy nắng do uốn nhuộm\", \"Lưu hương nước hoa hoa hồng táo ngọt ngào suốt cả ngày\"]','[\"Pro-Vitamin B5 Liposome\", \"Viên nang Serum Vàng\", \"Glycerin đậm đặc\"]','Sau khi gội đầu, vuốt bớt nước và thoa đều kem ủ từ thân đến ngọn tóc, ủ trong 3-5 phút rồi xả sạch bằng nước ấm.','cham-soc-toc-ca-nhan/pantene/u-toc/hu-serum-u-toc-pantene-miracles-daily.jpg'),(19,'Tuýp Kem Ủ Xả Dưỡng Tóc Pantene Miracles Daily Moisture Conditioner',15,14,'Tuýp kem ủ xả hàng ngày Pantene Miracles với kết cấu đậm đặc như serum, có thể sử dụng thay dầu xả hàng ngày giúp mái tóc luôn suôn mượt và vào nếp tuyệt đối.','[\"Dùng được hàng ngày mà không làm nặng tóc hay bết da đầu\", \"Cung cấp độ ẩm mịn màng tức thì chỉ sau 30 giây\", \"Dạng tuýp nắp bật tiện lợi, sạch sẽ khi dùng trong phòng tắm\"]','[\"Pro-Vitamin Complex\", \"Amino Acids\", \"Dầu dưỡng chất tự nhiên\"]','Sau khi gội đầu, thoa một lượng kem vừa đủ lên thân và ngọn tóc, xoa bóp nhẹ nhàng trong 1 phút rồi xả sạch.','cham-soc-toc-ca-nhan/pantene/u-toc/tuyp-serum-u-toc-pantene-miracles-daily.jpg'),(20,'Dầu Gội Chuẩn Salon TRESemmé Salon Rebond Ngăn Rụng Tóc',15,17,'Dầu gội TRESemmé Salon Rebond với công nghệ TRESplex Rebond tiên tiến len lỏi vào từng sợi tóc để hàn gắn các liên kết tóc bị đứt gãy do hóa chất uốn nhuộm, giảm rụng tóc gấp 10 lần.','[\"Tái kết nối các liên kết tóc hư tổn do uốn, nhuộm, tẩy tóc\", \"Giảm gãy rụng tóc tới 98% cho mái tóc chắc khỏe chuẩn salon\", \"Mái tóc dày dặn và đàn hồi tràn đầy sức sống\"]','[\"Công nghệ TRESplex Rebond\", \"Protein thủy phân\", \"Keratin phục hồi\"]','Thoa đều dầu gội lên tóc ướt, mát-xa tạo bọt nhẹ nhàng và xả sạch lại bằng nước.','cham-soc-toc-ca-nhan/tresemme/dau-goi/dau-goi-tresemme-ngan-gay-rung-toc.jpg'),(21,'Dầu Gội TRESemmé Keratin Smooth Tinh Dầu Argan Vào Nếp Suôn Mượt',15,17,'Dầu gội TRESemmé Keratin Smooth bổ sung tinh dầu Argan quý giá từ Maroc và hàm lượng Keratin đậm đặc, đem lại 5 hiệu quả sau 1 lần gội: tóc vào nếp - bóng mượt - mềm mại - giảm xơ - gỡ rối.','[\"Giữ nếp tóc suôn mượt chuẩn sàn diễn suốt 72 giờ\", \"Kiểm soát tình trạng tóc khô xơ và bông xù trong thời tiết ẩm\", \"Hương thơm sang trọng, quý phái lưu hương suốt ngày dài\"]','[\"Keratin protein đậm đặc\", \"Tinh dầu Argan hữu cơ Maroc\"]','Tạo bọt với nước trên tóc ướt, xoa bóp nhẹ nhàng da đầu và thân tóc, sau đó xả sạch.','cham-soc-toc-ca-nhan/tresemme/dau-goi/dau-goi-tresemme-vao-nep-suon-muot.jpg'),(22,'Dầu Xả TRESemmé Keratin Smooth Vào Nếp Mượt Mà Suốt 72 Giờ',15,17,'Dầu xả TRESemmé Keratin Smooth với công thức chứa tinh dầu Argan và Keratin, thẩm thấu sâu nuôi dưỡng từng sợi tóc, mang lại mái tóc bóng mượt bồng bềnh chuẩn Salon ngay tại nhà.','[\"Khóa ẩm và làm mềm mượt bề mặt sợi tóc ngay tức thì\", \"Gỡ rối nhanh chóng, giúp chải tóc êm mượt không rụng\", \"Tạo màng bảo vệ tóc trước nhiệt máy sấy và máy tạo kiểu\"]','[\"Tinh dầu Argan Maroc\", \"Keratin thủy phân\", \"Dimethicone bảo vệ tóc\"]','Sau khi gội đầu, vuốt kem xả từ thân đến ngọn tóc (tránh chân tóc), ủ trong 2-3 phút rồi xả sạch.','cham-soc-toc-ca-nhan/tresemme/dau-xa/dau-xa-tresemme-vao-nep-suon-muot.jpg'),(23,'Tinh Dầu Serum Dưỡng Tóc TRESemmé Keratin Smooth Shine Serum 100ml',15,17,'Serum dưỡng tóc TRESemmé Keratin Smooth Shine Serum dạng dầu dưỡng nhẹ tênh không bết dính, ngay lập tức đem lại độ bóng sáng gương và làm mềm mượt các lọn tóc xơ rối.','[\"Cung cấp độ bóng mượt rạng rỡ tức thì cho mái tóc\", \"Chống nhiệt độ cao lên tới 230 độ C trước khi kẹp tóc hoặc sấy\", \"Kiểm soát lọn tóc con chỉa xù, giữ nếp lọn xoăn tự nhiên\"]','[\"Dầu Argan Marula nguyên chất\", \"Hạt dầu Keratin siêu nhẹ\"]','Lấy 2-3 giọt serum ra lòng bàn tay xoa đều, vuốt nhẹ lên tóc ẩm hoặc tóc khô trước khi tạo kiểu.','cham-soc-toc-ca-nhan/tresemme/serum-duong-toc/serum-duong-toc-100ml.jpg'),(24,'Kem Ủ Tóc Phục Hồi Hư Tổn Nặng TRESemmé Bond Repair Treatment',15,17,'Kem ủ tóc TRESemmé Bond Repair với công nghệ liên kết chuyên sâu cấp độ salon, giải cứu mái tóc khô xơ chẻ ngọn do uốn nhuộm và tẩy tóc nhiều lần.','[\"Hàn gắn liên kết protein tóc bị đứt gãy sau tẩy nhuộm\", \"Trả lại độ đàn hồi, chắc khỏe và óng mượt cho sợi tóc\", \"Hiệu quả phục hồi rõ rệt ngay từ lần ủ đầu tiên\"]','[\"Công nghệ TRESplex\", \"Protein gạo thủy phân\", \"Lipid nuôi dưỡng\"]','Dùng sau bước gội, thoa đều lên toàn bộ thân và ngọn tóc, ủ trong 5-10 phút rồi xả sạch với nước ấm.','cham-soc-toc-ca-nhan/tresemme/u-toc/kem-u-toc-tresemme-bond-repair.jpg'),(25,'Kem Ủ Tóc TRESemmé Keratin Smooth Deep Smoothing Mask',15,17,'Kem ủ tóc TRESemmé Keratin Smooth Deep Smoothing Mask cung cấp liệu trình dưỡng tóc chuyên nghiệp chuẩn salon tại nhà, biến mái tóc xơ rối thành mái tóc suôn mượt như dải lụa.','[\"Nuôi dưỡng sâu từng sợi tóc xơ rối khó vào nếp\", \"Kiểm soát tình trạng tóc xù và tĩnh điện suốt tuần\", \"Cho mái tóc độ bóng bẩy, óng ả và mềm mại tối đa\"]','[\"Keratin đậm đặc\", \"Dầu hạt mỡ Argan\", \"Dưỡng chất Marula\"]','Sử dụng 1-2 lần mỗi tuần. Thoa kem ủ từ thân đến ngọn tóc ướt, massage nhẹ nhàng và ủ 5 phút trước khi xả sạch.','cham-soc-toc-ca-nhan/tresemme/u-toc/kem-u-toc-tresemme-keratin-smooth.jpg'),(26,'Sáp Dưỡng Ẩm Đa Năng Vaseline Pure Petroleum Jelly Original',13,18,'Sáp dưỡng ẩm Vaseline 100% Pure Petroleum Jelly trải qua quy trình thanh lọc 3 lần độc quyền, là bảo bối cấp cứu làn da nứt nẻ, dưỡng môi mềm mọng và làm dịu vết bỏng nhẹ.','[\"Khóa ẩm 100% ngăn chặn hiện tượng mất nước qua da\", \"Làm mềm nhanh làn môi khô nứt, da tay, gót chân chai sần\", \"Độ tinh khiết 100%, an toàn cho cả làn da nhạy cảm và trẻ em\"]','[\"100% White Petrolatum tinh khiết\"]','Thoa trực tiếp một lượng sáp vừa đủ lên môi, bàn tay, gót chân hoặc bất cứ vùng da khô ráp nào.','cham-soc-toc-ca-nhan/vaseline/sap-duong-da/sap-duong-da-vaseline-original.jpg'),(27,'Serum Dưỡng Thể Chống Lão Hóa Sáng Da Vaseline Gluta-Hya Flawless Bright / Dewy Radiance',13,18,'Serum dưỡng thể Vaseline Gluta-Hya với công nghệ GlutaGlow có sức mạnh sáng da gấp 10 lần Vitamin C kết hợp Hyaluronic Acid đậm đặc, đem lại làn da toàn thân căng bóng rạng ngời.','[\"Tác động sáng da và giảm đốm sắc tố gấp 10 lần Vitamin C thông thường\", \"Hyaluronic Acid ngậm nước cho làn da căng bóng sương mai\", \"Kết cấu dạng giọt nước tan ngay khi chạm vào da, không nhờn dính\"]','[\"GlutaGlow độc quyền\", \"Hyaluron (Hyaluronic Acid)\", \"10x Pro-Retinol / Niacinamide\"]','Thoa đều serum lên toàn thân mỗi ngày 2 lần vào buổi sáng và tối sau khi tắm.','cham-soc-toc-ca-nhan/vaseline/serum-duong-am/serum-duong-the-vaseline-gluta-hya.jpg'),(28,'Sữa Dưỡng Thể Vaseline Intensive Care Cocoa Glow Chiết Xuất Bơ Ca Cao',13,18,'Sữa dưỡng thể Vaseline Intensive Care Cocoa Glow chứa 100% bơ hạt ca cao và bơ hạt mỡ tự nhiên kết hợp các giọt sáp Vaseline Jelly siêu nhỏ, phục hồi làn da khô ráp và lưu hương ca cao quyến rũ.','[\"Dưỡng ẩm chuyên sâu cho làn da khô, sần sùi trở nên mềm mại\", \"Chiết xuất bơ ca cao nuôi dưỡng làn da sáng khỏe bóng bẩy tự nhiên\", \"Mùi hương chocolate ngọt ngào, ấm áp dễ chịu\"]','[\"100% Pure Cocoa & Shea Butter\", \"Vi giọt sáp Vaseline Jelly\", \"Glycerin\"]','Thoa đều sữa dưỡng thể lên cánh tay, chân và toàn thân mỗi ngày sau khi tắm sạch.','cham-soc-toc-ca-nhan/vaseline/sua-duong-the/sua-duong-the-vaseline-intensive-carecocoa.jpg'),(29,'Sữa Dưỡng Thể Vaseline Intensive Care Vanilla Comfort Hương Vani',13,18,'Sữa dưỡng thể Vaseline Intensive Care Vanilla Comfort cấp ẩm và xoa dịu làn da mệt mỏi với hương thơm vani ngọt ngào thư giãn, thẩm thấu nhanh mang lại làn da mượt mà.','[\"Làm dịu và cấp ẩm sâu cho da không bị khô căng\", \"Hương thơm vanilla ngọt lịm mang lại cảm giác thư thái dễ chịu\", \"Thấm nhanh không gây nhờn dính trên quần áo\"]','[\"Chiết xuất Vanilla\", \"Vi giọt sáp Vaseline Jelly\", \"Hệ dưỡng ẩm Intensive Care\"]','Lấy lượng sữa dưỡng thể vừa đủ thoa đều khắp cơ thể hàng ngày.','cham-soc-toc-ca-nhan/vaseline/sua-duong-the/sua-duong-the-vaseline-vanillacomfort.jpg'),(30,'Tinh Chất Dưỡng Thể Chống Nắng Vaseline Healthy Bright Daily Sun Refreshing SPF 50+ PA++++',13,18,'Serum dưỡng thể chống nắng Vaseline 50X bảo vệ da vượt trội trước tia UVA/UVB và ánh sáng xanh với chỉ số SPF 50+ PA++++, kết hợp Niacinamide dưỡng sáng da toàn thân.','[\"Bảo vệ da toàn diện trước tia UVA, UVB và bụi mịn PM 2.5 với SPF 50+ PA++++\", \"Dưỡng trắng da toàn thân, ngăn ngừa sạm nám và cháy nắng\", \"Cảm giác mát lạnh sảng khoái trên da khi vừa thoa\"]','[\"Bộ màng lọc chống nắng SPF 50+ PA++++\", \"Niacinamide (Vitamin B3)\", \"Chiết xuất bạc hà mát lạnh\"]','Thoa đều lên da cơ thể trước khi ra ngoài trời ít nhất 15-20 phút. Thoa lại sau mỗi 2-3 giờ nếu hoạt động ngoài trời lâu.','cham-soc-toc-ca-nhan/vaseline/tinh-chat-duong-the/tinh-chat-duong-the-vaseline-healthy-brightsun.jpg'),(31,'Gel Giảm Mụn & Thông Thoáng Lỗ Chân Lông CeraVe Blemish Control Gel 40ml',5,2,'Gel giảm mụn CeraVe Blemish Control Gel với công thức dịu nhẹ chứa 2% Salicylic Acid (BHA), AHA (Glycolic & Lactic Acid) kết hợp 3 Ceramides thiết yếu giúp giảm mụn rõ rệt sau 3 ngày, mờ vết thâm mà không làm tổn hại màng ẩm da.','[\"Giảm mụn sưng viêm, gom cồi mụn và ngăn ngừa mụn mới xuất hiện\", \"Tẩy tế bào chết nhẹ nhàng, làm thông thoáng và thu nhỏ lỗ chân lông\", \"Phục hồi và duy trì hàng rào bảo vệ tự nhiên của da nhờ 3 Ceramides thiết yếu\"]','[\"2% Salicylic Acid (BHA)\", \"Glycolic & Lactic Acid (AHA)\", \"3 Ceramides thiết yếu (1, 3, 6-II)\", \"Niacinamide (Vitamin B3)\"]','Làm sạch da mặt bằng sữa rửa mặt và toner. Lấy lượng gel vừa đủ thoa đều lên vùng da mụn hoặc toàn bộ khuôn mặt vào buổi tối. Ban ngày cần dùng kem chống nắng SPF 30+.','chamsocda-anh/cerave/gel-giam-mun/cerave-gel-giam-mun-1.jpg'),(32,'Kem Dưỡng Ẩm Chuyên Sâu Cho Da Khô Đến Rất Khô CeraVe Moisturizing Cream',5,2,'Kem dưỡng ẩm CeraVe Moisturizing Cream ứng dụng công nghệ MVE độc quyền giúp giải phóng liên tục các thành phần dưỡng ẩm suốt 24 giờ. Chứa 3 Ceramides thiết yếu và Hyaluronic Acid giúp phục hồi màng bảo vệ da cho cả mặt và toàn thân.','[\"Cấp ẩm chuyên sâu và duy trì độ ẩm liên tục suốt 24 giờ\", \"Phục hồi màng bảo vệ da suy yếu, giảm tình trạng bong tróc và khô ráp\", \"Chất kem đậm đặc nhưng thẩm thấu êm ái, không gây bít tắc lỗ chân lông\"]','[\"3 Ceramides thiết yếu (1, 3, 6-II)\", \"Hyaluronic Acid\", \"Công nghệ phân phối dưỡng chất MVE\"]','Thoa đều lên da mặt và cơ thể bất cứ khi nào cảm thấy da khô, đặc biệt là sau khi tắm hoặc rửa mặt.','chamsocda-anh/cerave/kem-duong-am/cerave-cong-dung-chuyen-sau-01.jpg'),(33,'Nước Tẩy Trang Cấp Ẩm & Dịu Nhẹ CeraVe Micellar Cleansing Water 295ml',6,2,'Nước tẩy trang CeraVe Micellar Cleansing Water 3 trong 1 nhẹ nhàng loại bỏ lớp trang điểm, bụi bẩn và dầu thừa mà không cần chà xát mạnh hay rửa lại với nước, giúp làm dịu và bảo vệ độ ẩm tự nhiên của da.','[\"Làm sạch sâu lớp makeup, bụi mịn và dầu thừa chỉ trong 1 bước\", \"Làm dịu và cấp nước cho da tức thì, không gây cảm giác khô căng nhờn dính\", \"Không cồn, không hương liệu, an toàn cho cả vùng da mắt nhạy cảm\"]','[\"Công nghệ hạt Micellar\", \"3 Ceramides thiết yếu\", \"Niacinamide\"]','Thấm ướt bông tẩy trang, nhẹ nhàng lau khắp mặt, mắt và môi theo chiều cấu tạo da. Không cần rửa lại với nước.','chamsocda-anh/cerave/nuoc-tay-trang/cerave-nuoc-tay-trang-1.png'),(34,'Sữa Chống Nắng Khoáng Chất Vật Lý CeraVe Hydrating Mineral Sunscreen SPF 50',2,2,'Sữa chống nắng 100% khoáng chất CeraVe Mineral Sunscreen SPF 50 với Zinc Oxide và Titanium Dioxide tạo lớp màng bảo vệ quang phổ rộng chống tia UVA/UVB, đồng thời khóa ẩm và làm dịu da nhạy cảm.','[\"Chống nắng phổ rộng bảo vệ da tối ưu trước tác hại của tia UVA và UVB\", \"100% màng lọc khoáng chất an toàn cho cả làn da nhạy cảm nhất\", \"Khóa ẩm và củng cố hàng rào bảo vệ da với Ceramides và Niacinamide\"]','[\"Zinc Oxide & Titanium Dioxide\", \"3 Ceramides thiết yếu\", \"Hyaluronic Acid\", \"Niacinamide\"]','Thoa đều lên mặt và cổ 15 phút trước khi ra nắng. Thoa lại sau mỗi 2 tiếng hoặc sau 80 phút bơi lội/đổ mồ hôi.','chamsocda-anh/cerave/sua-chong-nang/cerave-sua-chong-nang-1.jpg'),(35,'Sữa Rửa Mặt Tạo Bọt Làm Sạch Sâu CeraVe Foaming Facial Cleanser',3,2,'Sữa rửa mặt tạo bọt CeraVe Foaming Cleanser được phát triển bởi các bác sĩ da liễu, nhẹ nhàng cuốn trôi dầu thừa và bụi bẩn tích tụ sâu trong lỗ chân lông mà không làm phá vỡ hàng rào ẩm tự nhiên của da.','[\"Làm sạch sâu bã nhờn dư thừa, ngăn ngừa hình thành mụn mới\", \"Không gây khô căng kít, bảo toàn màng ẩm tự nhiên sau khi rửa mặt\", \"Làm dịu da và củng cố liên kết lipid nhờ Ceramides và Niacinamide\"]','[\"3 Ceramides thiết yếu (1, 3, 6-II)\", \"Niacinamide\", \"Hyaluronic Acid\"]','Lấy một lượng gel vừa đủ ra lòng bàn tay ướt, tạo bọt nhẹ nhàng và mát-xa khắp khuôn mặt trong 60 giây rồi rửa sạch bằng nước ấm.','chamsocda-anh/cerave/sua-rua-mat/cerave-giay-chung-nhan.jpg'),(36,'Thạch Hoa Hồng Dưỡng Ẩm Cấp Nước Cocoon True Rose Hydro Cream 50ml',5,5,'Thạch hoa hồng Cocoon với kết cấu mọng nước chứa nước hoa hồng hữu cơ chưng cất và các axit amin tự nhiên, thẩm thấu nhanh như nước giúp cấp ẩm sâu và nuôi dưỡng làn da mịn màng ngậm nước suốt 24h.','[\"Nuôi dưỡng và phục hồi độ ẩm cho làn da ẩm mượt suốt cả ngày\", \"Làm dịu làn da mệt mỏi, hỗ trợ se khít lỗ chân lông\", \"Kết cấu dạng thạch mỏng nhẹ tan trên da, không gây nhờn rít\"]','[\"Nước cất hoa hồng hữu cơ Cao Bằng\", \"Hyaluronic Acid phân tử nhỏ\", \"Pentavitin\", \"Axit Amin tự nhiên\"]','Lấy một lượng thạch vừa đủ thoa đều lên toàn bộ khuôn mặt và cổ vào mỗi sáng và tối sau bước serum.','chamsocda-anh/cocoon/kem-duong-am/cocoon-kem-duong-am-chiet-xuat-hoa-hong-1.jpg'),(37,'Mặt Nạ Cánh Hoa Hồng Tươi Dưỡng Ẩm & Làm Mềm Da Cocoon 30ml',7,5,'Mặt nạ hoa hồng Cocoon chứa những cánh hoa hồng tươi nghiền nhuyễn hòa quyện trong lớp gel mọng nước, mang đến cảm giác thư thái và phục hồi làn da xỉn màu, khô ráp tức thì.','[\"Cấp ẩm và phục hồi sức sống cho làn da khô mệt mỏi\", \"Giảm cảm giác căng rát, làm mềm mịn bề mặt biểu bì da\", \"Mùi hương hoa hồng tự nhiên thuần khiết giúp thư giãn tinh thần\"]','[\"Cánh hoa hồng tươi Cao Bằng\", \"Chiết xuất nha đam\", \"Hyaluronic Acid\"]','Thoa một lượng mặt nạ đều lên da mặt sạch, thư giãn trong 15-20 phút rồi rửa sạch lại với nước.','chamsocda-anh/cocoon/mat-na/cocoon-mat-na-1.jpg'),(38,'Nước Tẩy Trang Bí Đao Làm Sạch Dầu Mụn Cocoon Winter Melon Micellar Water',6,5,'Nước tẩy trang bí đao Cocoon ứng dụng công nghệ Micellar kết hợp chiết xuất bí đao thanh nhiệt, tràm trà và rau má, giúp làm sạch sâu lớp trang điểm cứng đầu và kiểm soát dầu nhờn cho da mụn.','[\"Làm sạch sâu bụi bẩn, bã nhờn và cặn trang điểm bám chặt\", \"Kháng khuẩn, làm dịu các nốt mụn viêm sưng và giảm tiết dầu\", \"Thuần chay 100%, không cồn, không sulfate, không cay mắt\"]','[\"Chiết xuất bí đao\", \"Tinh dầu tràm trà (Tea Tree Oil)\", \"Chiết xuất rau má (Centella)\", \"Betaine\"]','Thấm đều nước tẩy trang lên bông cotton, nhẹ nhàng lau sạch khắp mặt và cổ. Có thể dùng nhiều miếng bông cho đến khi sạch hoàn toàn.','chamsocda-anh/cocoon/nuoc-tay-trang/nuoc-tay-trang-bi-dao/coccoon-nuoc-tay-trang-bi-dao-140ml-1.jpg'),(39,'Nước Tẩy Trang Hoa Sen Làm Dịu Da Nhạy Cảm Cocoon Lotus Micellar Water',6,5,'Nước tẩy trang hoa sen Cocoon dành riêng cho làn da nhạy cảm, dễ kích ứng hoặc sau điều trị. Chiết xuất hoa sen thanh nhã kết hợp vitamin B12 giúp phục hồi màng ẩm và làm sáng da dịu êm.','[\"Làm sạch nhẹ dịu tuyệt đối, không gây rát da hay ửng đỏ\", \"Làm dịu tình trạng kích ứng, củng cố hàng rào ẩm cho da nhạy cảm\", \"Dưỡng sáng nhẹ nhàng và chống oxy hóa nhờ chiết xuất hoa sen\"]','[\"Chiết xuất hoa sen Đồng Tháp\", \"Vitamin B12\", \"Beta-Glucan\", \"Hạt làm sạch Micellar\"]','Thấm dung dịch ra bông tẩy trang, lau nhẹ nhàng khắp mặt, mắt và môi. Không cần chà xát mạnh.','chamsocda-anh/cocoon/nuoc-tay-trang/nuoc-tay-trang-hat-sen/cocoon-nuoc-tay-trang-hat-sen-0.webp'),(40,'Sữa Chống Nắng Bí Đao Quang Phổ Rộng Cocoon Winter Melon Sun Fluid SPF 50+ PA++++ 50ml',2,5,'Sữa chống nắng bí đao Cocoon với công thức quang phổ rộng kết hợp các màng lọc thế hệ mới tiên tiến (Tinosorb S, Tinosorb M, Uvinul A+, Uvinul T150), đem lại khả năng bảo vệ cực cao và lớp finish ráo mịn không bóng dầu.','[\"Bảo vệ da vượt trội trước tia UVA, UVB, ánh sáng xanh HEV với chỉ số SPF 50+ PA++++\", \"Kiềm dầu hiệu quả, không gây bết dính hay vón cục trên da\", \"Không để lại vệt trắng, tạo hiệu ứng màng ẩm tự nhiên thoáng nhẹ\"]','[\"Màng lọc chống nắng thế hệ mới\", \"Chiết xuất bí đao\", \"Syn-Actu (kháng viêm)\", \"Niacinamide\"]','Lắc đều trước khi dùng. Thoa lượng sữa chống nắng vừa đủ (khoảng 2 ngón tay) lên mặt và cổ trước khi ra ngoài 20 phút.','chamsocda-anh/cocoon/sua-chong-nang/sua-chong-nang-bi-dao/cocoon-kem-chong-nang-bi-dao-1.webp'),(41,'Sữa Chống Nắng Hoa Sen Nâng Tông Tự Nhiên Cocoon Lotus Sun Fluid SPF 50+ PA++++',2,5,'Sữa chống nắng hoa sen Cocoon bảo vệ da tối đa kết hợp hiệu ứng nâng tông trắng hồng tự nhiên, che khuyết điểm nhẹ nhàng giúp bạn tự tin ra ngoài mà không cần trang điểm cầu kỳ.','[\"Chống nắng phổ rộng bảo vệ da toàn diện SPF 50+ PA++++\", \"Nâng tông trắng hồng tự nhiên, kiềm dầu nhẹ và làm mịn lỗ chân lông\", \"Chiết xuất hoa sen chống oxy hóa và bảo vệ tế bào da khỏi lão hóa\"]','[\"Màng lọc quang phổ rộng\", \"Chiết xuất hoa sen\", \"Vitamin B12\", \"Bột ngọc trai tạo hiệu ứng sáng mịn\"]','Thoa đều lên toàn bộ khuôn mặt vào bước cuối cùng của chu trình dưỡng da buổi sáng.','chamsocda-anh/cocoon/sua-chong-nang/sua-chong-nang-hat-sen/cocoon-kem-chong-nang-sen-1.png'),(42,'Gel Rửa Mặt Bí Đao Giảm Dầu Mụn Cocoon Winter Melon Gel Cleanser',3,5,'Gel rửa mặt bí đao Cocoon có độ pH 5.5 lý tưởng cân bằng da, chứa chiết xuất bí đao, rau má, tràm trà và BHA giúp làm sạch bụi bẩn, giảm bã nhờn và cải thiện mụn ẩn mụn viêm hiệu quả.','[\"Làm sạch sâu bã nhờn và cặn bẩn trong lỗ chân lông\", \"Giảm tiết dầu thừa, làm dịu các nốt mụn sưng đỏ\", \"Độ pH 5.5 chuẩn cân bằng, không gây cảm giác khô căng sau khi rửa\"]','[\"Chiết xuất bí đao\", \"Rau má\", \"Tinh dầu tràm trà\", \"Vitamin B3 (Niacinamide)\"]','Lấy một lượng gel vừa đủ xoa đều với nước tạo bọt mịn, mát-xa nhẹ nhàng khắp mặt rồi rửa sạch lại với nước.','chamsocda-anh/cocoon/sua-rua-mat/sua-rua-mat-bi-dao/cocoon-sua-rua-mat-bi-dao-140ml-1.jpg'),(43,'Sữa Rửa Mặt Dịu Nhẹ Chiết Xuất Hoa Sen Cocoon Lotus Cleanser',3,5,'Sữa rửa mặt hoa sen Cocoon với công thức dịu nhẹ không xà phòng dành riêng cho da nhạy cảm và da khô, nhẹ nhàng làm sạch tạp chất mà vẫn nâng niu màng ẩm tự nhiên của da.','[\"Làm sạch êm dịu, không gây kích ứng hay châm chích da\", \"Duy trì độ ẩm tự nhiên, cho làn da mềm mịn sau khi rửa\", \"Chiết xuất hoa sen chống oxy hóa, nuôi dưỡng da tươi sáng\"]','[\"Chiết xuất hoa sen tươi\", \"Vitamin B12\", \"Glycerin thực vật\", \"Axit Amin dịu nhẹ\"]','Tạo bọt với nước trên lòng bàn tay, mát-xa nhẹ nhàng lên da ướt và rửa sạch lại với nước.','chamsocda-anh/cocoon/sua-rua-mat/sua-rua-mat-hat-sen/cocoon-sua-rua-mat-hat-sen-140ml-1.jpg'),(44,'Gel Rửa Mặt Nghệ Hưng Yên Sáng Da & Mờ Thâm Cocoon Turmeric Cleanser',3,5,'Gel rửa mặt nghệ Hưng Yên Cocoon kết hợp chiết xuất củ nghệ giàu Curcumin, 4% AHA và Betaine giúp làm sạch tế bào chết bề mặt, làm mờ vết thâm mụn và dưỡng da sáng khỏe rạng ngời.','[\"Làm mờ vết thâm sau mụn và dưỡng sáng đều màu da\", \"Tẩy tế bào chết nhẹ nhàng nhờ 4% AHA giúp da láng mịn\", \"Chống oxy hóa và củng cố độ săn chắc cho làn da\"]','[\"Chiết xuất nghệ Hưng Yên giàu Curcumin\", \"4% AHA (Lactic Acid)\", \"Betaine\", \"Dầu hạt cà rốt\"]','Tạo bọt với nước trên tay ướt, xoa bóp nhẹ nhàng khắp mặt trong 60 giây và rửa sạch lại bằng nước sạch.','chamsocda-anh/cocoon/sua-rua-mat/sua-rua-mat-nghe/cocoon-sua-rua-mat-nghe-140ml-1.webp'),(45,'Cà Phê Đắk Lắk Làm Sạch Da Chết Mặt Cocoon Dak Lak Coffee Face Polish 150ml',8,5,'Tẩy tế bào chết mặt cà phê Đắk Lắk Cocoon từ những hạt cà phê Robusta xay nhuyễn mịn hòa quyện cùng bơ ca cao Tiền Giang, nhẹ nhàng cuốn trôi lớp sừng già cỗi mang lại làn da mịn màng thơm ngát.','[\"Làm sạch tế bào chết nhẹ êm, không gây trầy xước hay rát da\", \"Cung cấp năng lượng chống oxy hóa giúp da sáng khỏe, đều màu\", \"Bơ ca cao khóa ẩm giữ da luôn mềm mượt sau khi tẩy da chết\"]','[\"Hạt cà phê Đắk Lắk xay siêu mịn\", \"Bơ ca cao Tiền Giang\", \"Dầu hoa rum\", \"Vitamin E\"]','Thoa đều lên da mặt ẩm, mát-xa nhẹ nhàng theo chuyển động tròn trong 2-3 phút rồi rửa sạch với nước. Dùng 1-2 lần/tuần.','chamsocda-anh/cocoon/tay-da-chet/tay-da-chet-mat/cocoon-tay-da-chet-mat-ca-phe-dak-lak-1.png'),(46,'Cà Phê Đắk Lắk Làm Sạch Da Chết Môi Cocoon Dak Lak Coffee Lip Scrub 5g',8,5,'Tẩy tế bào chết môi cà phê Đắk Lắk Cocoon dạng thỏi son tiện lợi, lấy đi các mảng da môi bong tróc khô nứt, trả lại đôi môi hồng hào căng mịn giúp thoa son chuẩn màu và lâu trôi.','[\"Loại bỏ vảy da chết khô ráp trên môi nhẹ nhàng\", \"Cung cấp dưỡng chất giữ môi mềm mọng suốt cả ngày\", \"Mùi thơm cà phê ngọt bùi cực kỳ hấp dẫn\"]','[\"Cà phê Đắk Lắk\", \"Bơ hạt mỡ\", \"Dầu mắc-ca\"]','Làm ẩm môi, thoa sản phẩm lên môi và mát-xa nhẹ nhàng trong 30 giây, sau đó dùng khăn ẩm lau sạch.','chamsocda-anh/cocoon/tay-da-chet/tay-da-chet-moi/cocoon-tay-da-chet-moi-1.jpg'),(47,'Cà Phê Đắk Lắk Làm Sạch Da Chết Cơ Thể Cocoon Dak Lak Coffee Body Polish 200ml',8,5,'Sản phẩm tẩy da chết body bán chạy số 1 tại Việt Nam từ hạt cà phê Đắk Lắk nguyên chất kết hợp bơ ca cao, đánh bay vùng da sần sùi ở khuỷu tay, đầu gối và cải thiện tình trạng viêm nang lông.','[\"Làm sạch sâu lớp sừng già cỗi toàn thân, giảm bít tắc lỗ chân lông\", \"Cải thiện hiệu quả tình trạng viêm nang lông và mụn lưng\", \"Cho làn da toàn thân sáng mịn, mềm mại như lụa ngay lần đầu dùng\"]','[\"Cà phê Robusta Đắk Lắk nguyên chất\", \"Bơ ca cao Tiền Giang\", \"Dầu đậu nành\"]','Thoa một lượng kem lên cơ thể ướt, mát-xa đều khắp người từ 5-10 phút rồi tráng sạch với nước.','chamsocda-anh/cocoon/tay-da-chet/tay-da-chet-toan-than/cocoon-tay-da-chet-toan-than-1.jpg'),(48,'Nước Bí Đao Cân Bằng Da Giảm Dầu Mụn Cocoon Winter Melon Toner',4,5,'Nước bí đao cân bằng da Cocoon chứa chiết xuất bí đao, rau má và tinh dầu tràm trà kết hợp 7% Niacinamide, giúp cân bằng độ pH, kiểm soát bã nhờn và se khít lỗ chân lông hiệu quả.','[\"Cân bằng độ ẩm và đưa độ pH da về mức lý tưởng sau khi rửa mặt\", \"Hạn chế tiết dầu thừa và kháng khuẩn, ngừa mụn tái phát\", \"Làm dịu và giảm đỏ các nốt mụn sưng tấy\"]','[\"Chiết xuất bí đao\", \"Tinh dầu tràm trà\", \"7% Niacinamide\", \"Chiết xuất rau má\"]','Sau khi rửa mặt, cho toner ra bông hoặc lòng bàn tay, vỗ nhẹ nhàng khắp mặt và cổ cho thẩm thấu hoàn toàn.','chamsocda-anh/cocoon/toner/toner-bi-dao/cocoon-toner-bi-dao-140ml-1.jpg'),(49,'Nước Hoa Sen Cân Bằng & Cấp Ẩm Cho Da Nhạy Cảm Cocoon Lotus Toner',4,5,'Nước hoa sen Cocoon với dưỡng chất hoa sen và Beta-Glucan làm dịu tức thì làn da nhạy cảm mệt mỏi, bổ sung lượng nước dồi dào giúp bề mặt da luôn mềm mại và căng tràn sức sống.','[\"Làm dịu kích ứng, ngứa rát và mẩn đỏ trên da nhạy cảm\", \"Cấp nước tầng sâu, chuẩn bị cho các bước dưỡng tiếp theo hấp thụ tốt hơn\", \"Tăng cường sức đề kháng cho hàng rào sinh học của da\"]','[\"Nước cất hoa sen Đồng Tháp\", \"Beta-Glucan\", \"Vitamin B12\", \"Hyaluronic Acid\"]','Vỗ nhẹ toner lên da mặt sạch sau khi rửa mặt vào buổi sáng và tối.','chamsocda-anh/cocoon/toner/toner-hoa-sen/cocoon-toner-sen-140ml-1.jpg'),(50,'Kem Chống Nắng Dưỡng Ẩm Hàng Ngày Innisfree Daily UV Defense Sunscreen SPF 50+ PA++++',2,7,'Kem chống nắng Innisfree Daily UV Defense với công thức gốc nước mỏng nhẹ gốc thực vật từ đảo Jeju, đem lại khả năng chống nắng toàn diện mà thẩm thấu nhanh như lotion, không để lại màng trắng hay bết dính.','[\"Bảo vệ da mạnh mẽ trước tia UVA và UVB với chỉ số SPF 50+ PA++++\", \"Cấp ẩm cho da ngậm nước căng bóng suốt ngày dài\", \"Lớp finish trong suốt tự nhiên, làm lớp lót trang điểm hoàn hảo\"]','[\"Chiết xuất trà xanh Jeju\", \"Chiết xuất rau má Centella\", \"Dầu hạt hướng dương\"]','Thoa đều lên mặt và cổ trước khi ra ngoài 15 phút. Thoa lại sau mỗi 2-3 giờ nếu vận động nhiều.','chamsocda-anh/innisfree/kem-chong-nang/innisfree-kem-chong-nang-01.jpg'),(51,'Kem Dưỡng Da Tay Hương Nước Hoa Đảo Jeju Innisfree Jeju Life Perfumed Hand Cream',13,7,'Kem dưỡng da tay Innisfree Jeju Life lưu giữ trọn vẹn hương thơm phong cảnh bốn mùa đảo Jeju, với chất kem xốp mềm giàu dưỡng chất giúp đôi bàn tay luôn mềm mại và thơm mát.','[\"Dưỡng ẩm sâu cho bàn tay mềm mịn, không còn khô ráp nứt nẻ\", \"Công nghệ lưu hương bán vĩnh viễn giữ mùi thơm nước hoa tinh tế suốt nhiều giờ\", \"Thấm nhanh không gây trơn nhờn khi cầm nắm hay bấm điện thoại\"]','[\"Bơ hạt mỡ\", \"Dầu olive\", \"Chiết xuất thảo mộc đảo Jeju\"]','Thoa một lượng kem nhỏ lên mu bàn tay và xoa đều khắp các ngón tay bất cứ khi nào cảm thấy khô.','chamsocda-anh/innisfree/kem-duong-da-tay/innisfree-kem-duong-da-tay-1.webp'),(52,'Mặt Nạ Đất Sét Tro Núi Lửa Hút Dầu Se Lỗ Chân Lông Innisfree Super Volcanic Pore Clay Mask 2X 100ml',7,7,'Mặt nạ đất sét tro núi lửa Innisfree 2X huyền thoại chứa cụm tro núi lửa Jeju kết hợp bột vỏ quả óc chó và AHA, đem lại giải pháp chăm sóc lỗ chân lông 10 trong 1: hút sạch bã nhờn, se khít lỗ chân lông và làm mịn da.','[\"Hút sạch 98% bã nhờn dư thừa và độc tố sâu trong lỗ chân lông\", \"Hỗ trợ làm giảm mụn đầu đen, mụn cám hiệu quả\", \"Đem lại cảm giác mát lạnh sảng khoái và thanh lọc da tức thì\"]','[\"Đá tro núi lửa Jeju Volcanic Clusters\", \"AHA tẩy da chết\", \"Bột vỏ quả óc chó\", \"Bột khoáng khoáng chất\"]','Sau khi rửa mặt, thoa mặt nạ lên toàn mặt (tránh mắt, môi), thư giãn 10-15 phút rồi mát-xa với nước ấm và rửa sạch. Dùng 1-2 lần/tuần.','chamsocda-anh/innisfree/mat-na/mat-na-dat-set-tu-da-tro-nui-lua-cham-soc-lo-chan-long/innisfree-mat-na-cham-soc-lo-chan-long-1.jpg'),(53,'Mặt Nạ Giấy Cấp Nước Làm Dịu Da Chiết Xuất Nha Đam Innisfree Squeeze Energy Mask Aloe',7,7,'Mặt nạ giấy Innisfree nha đam chiết xuất bằng phương pháp ép lạnh giữ trọn vẹn dưỡng chất tinh túy, giúp cấp ẩm dồi dào và xoa dịu làn da cháy nắng hoặc kích ứng mẩn đỏ.','[\"Cấp nước tức thì giúp hồi sinh làn da khô kiệt\", \"Làm dịu làn da bị cháy nắng hoặc ửng đỏ vì thời tiết nóng\", \"Chất liệu mặt nạ 100% cellulose thực vật ôm khít khuôn mặt\"]','[\"Chiết xuất nha đam tươi Jeju ép lạnh\", \"Glycerin\", \"Centella Asiatica\"]','Đắp mặt nạ lên mặt đã làm sạch trong 10-20 phút. Tháo mặt nạ và vỗ nhẹ cho tinh chất thẩm thấu.','chamsocda-anh/innisfree/mat-na/mat-na-giay-cap-nuoc-diu-da-nha-dam/innisfree-mat-na-giay-nha-dam-1.png'),(54,'Mặt Nạ Giấy Cấp Ẩm Sâu Trà Xanh Dưỡng Sáng Innisfree Squeeze Energy Mask Green Tea',7,7,'Mặt nạ giấy trà xanh Innisfree giàu 16 loại axit amin từ mầm trà xanh hữu cơ Beauty Green Tea đảo Jeju, cung cấp độ ẩm sâu và chống oxy hóa mạnh mẽ cho làn da sáng mịn khỏe mạnh.','[\"Cấp ẩm sâu và duy trì màng ẩm lâu dài cho da mềm mượt\", \"Chống oxy hóa, bảo vệ tế bào da khỏi các gốc tự do gây hại\", \"Giúp da thư giãn và sáng khỏe rạng ngời sau khi đắp\"]','[\"Chiết xuất mầm trà xanh Beauty Green Tea Jeju\", \"Axit amin tự nhiên\", \"Betaine\"]','Đắp lên da mặt trong 15-20 phút, sau đó gỡ mặt nạ và mát-xa nhẹ lượng tinh chất còn lại.','chamsocda-anh/innisfree/mat-na/mat-na-giay-cap-nuoc-diu-da-tra-xanh/innisfree-mat-na-giay-tra-xanh-1.png'),(55,'Mặt Nạ Giấy Rau Diếp Cá Giảm Mụn Innisfree Squeeze Energy Mask Heartleaf',7,7,'Mặt nạ giấy rau diếp cá Innisfree chứa tinh chất diếp cá làm dịu các vùng da mụn sưng viêm, thanh lọc bã nhờn và phục hồi làn da dầu mụn nhạy cảm.','[\"Làm dịu nhanh các nốt mụn viêm sưng và vết đỏ kích ứng\", \"Kháng khuẩn tự nhiên và cân bằng lượng dầu trên bề mặt da\", \"Mang lại cảm giác thanh mát, sảng khoái sau khi đắp\"]','[\"Chiết xuất rau diếp cá (Heartleaf)\", \"Panthenol\", \"Allantoin\"]','Đắp mặt nạ trong 15 phút, vỗ nhẹ tinh chất thẩm thấu vào da. Sử dụng 2-3 lần/tuần.','chamsocda-anh/innisfree/mat-na/mat-na-giay-diu-da-mun-tu-rau-diep-ca/innisfree-mat-na-giay-rau-nhip-ca-1.png'),(56,'Mặt Nạ Giấy Rau Má Phục Hồi Làm Dịu Da Innisfree Squeeze Energy Mask Centella',7,7,'Mặt nạ giấy rau má Innisfree là giải pháp cấp cứu cho làn da bị tổn thương sau mụn hoặc nhạy cảm với thời tiết, thúc đẩy tái tạo tế bào và tăng sức đề kháng cho da.','[\"Phục hồi và làm lành vùng da tổn thương, mẩn đỏ sau nặn mụn\", \"Tăng sinh màng ẩm và củng cố hàng rào bảo vệ da\", \"Dịu nhẹ không gây châm chích ngay cả trên da mỏng yếu\"]','[\"Chiết xuất rau má Centella Asiatica\", \"Madecassoside\", \"Hyaluronic Acid\"]','Đắp mặt nạ lên da sạch trong 15-20 phút, tháo ra và dùng ngón tay vỗ đều tinh chất.','chamsocda-anh/innisfree/mat-na/mat-na-giay-duong-am-da-diu-da-rau-ma/innisfree-mat-na-giay-rau-ma-1.webp'),(57,'Mặt Nạ Giấy Yến Mạch Dưỡng Ẩm Chuyên Sâu Innisfree Squeeze Energy Mask Oatmeal',7,7,'Mặt nạ giấy yến mạch Innisfree dạng tinh chất sữa đậm đặc, bổ sung lượng dưỡng chất dồi dào từ hạt yến mạch giúp nuôi dưỡng làn da khô ráp, bong tróc trở nên mịn màng như em bé.','[\"Dưỡng ẩm chuyên sâu cho da khô thô ráp thiếu dưỡng chất\", \"Cung cấp protein thực vật và lipid nuôi dưỡng bề mặt da căng mịn\", \"Dạng tinh chất sữa béo ngậy nuôi dưỡng sâu tầng biểu bì\"]','[\"Chiết xuất hạt yến mạch cô đặc\", \"Ceramide thực vật\", \"Bơ hạt mỡ\"]','Đắp mặt nạ trong 15-20 phút, mát-xa nhẹ nhàng lớp dưỡng chất dạng sữa trên da cho thẩm thấu.','chamsocda-anh/innisfree/mat-na/mat-na-giay-duong-am-da-yen-mach/innisfree-mat-na-giay-yen-mach-01.jpg'),(58,'Mặt Nạ Giấy Lựu Đỏ Chống Lão Hóa Căng Bóng Innisfree Squeeze Energy Mask Pomegranate',7,7,'Mặt nạ giấy chiết xuất lựu đỏ tươi đảo Jeju dồi dào chất chống oxy hóa Polyphenol và Vitamin C, giúp cải thiện độ đàn hồi, ngăn ngừa lão hóa và mang lại làn da căng bóng hồng hào.','[\"Chống lão hóa, tăng cường độ đàn hồi và săn chắc cho da\", \"Dưỡng da sáng hồng rạng rỡ, làm mờ các nếp nhăn li ti\", \"Cung cấp độ ẩm mịn mướt mượt tức thì\"]','[\"Nước ép lựu đỏ tươi nguyên chất\", \"Dầu hạt lựu\", \"Niacinamide\"]','Đắp mặt nạ lên da trong 15-20 phút rồi tháo ra, vỗ nhẹ dưỡng chất còn lại.','chamsocda-anh/innisfree/mat-na/mat-na-giay-lam-min-sang-da-huong-luu/ennisfree-mat-na-giay-huong-luu-1.png'),(59,'Phấn Phủ Bột Khoáng Kiềm Dầu Quốc Dân Innisfree No-Sebum Mineral Powder 5g',11,7,'Hộp phấn phủ bột kiềm dầu bán chạy số 1 Châu Á của Innisfree với thành phần khoáng chất tự nhiên đảo Jeju và bạc hà, hút sạch bã nhờn tức thì, giữ lớp trang điểm lâu trôi và da khô thoáng suốt 8 giờ.','[\"Kiểm soát bã nhờn và mồ hôi vượt trội suốt cả ngày\", \"Hạt phấn siêu mịn không màu, không gây mốc mặt hay nặng mặt\", \"Đa năng: dùng kiềm dầu mặt, set son môi, hút dầu chân tóc bết\"]','[\"Bột khoáng tự nhiên đảo Jeju\", \"Chiết xuất lá bạc hà mát lạnh\", \"Bột Silica vi hạt\"]','Dùng bông phấn dặm nhẹ nhàng lên vùng chữ T hoặc toàn bộ khuôn mặt sau khi trang điểm hoặc khi da đổ dầu.','chamsocda-anh/innisfree/phan-phu/innisfree-phan-phu-kiem-dau-1.webp'),(60,'Tinh Chất Dưỡng Ẩm Trà Xanh Cải Tiến Innisfree Green Tea Seed Hyaluronic Serum 80ml',4,7,'Serum trà xanh biểu tượng của Innisfree phiên bản nâng cấp kết hợp Beauty Green Tea và 5 loại Hyaluronic Acid viên nang phân tử nano, thẩm thấu sâu tới 15 tầng biểu bì giúp giải cứu làn da thiếu ẩm tức thì.','[\"Tăng cường độ ẩm sâu 724% ngay sau khi thoa\", \"Cải thiện và phục hồi màng bảo vệ da suy yếu chỉ sau 1 giờ\", \"Kết cấu serum trong veo, thấm cực nhanh không để lại cảm giác dính\"]','[\"Beauty Green Tea Jeju giàu axit amin\", \"5 loại Hyaluronic Acid viên nang siêu nhỏ\", \"Panthenol\"]','Sử dụng ngay sau bước rửa mặt (First Serum) để khóa ẩm tức thì, lấy 2-3 bơm thoa đều khắp mặt và cổ.','chamsocda-anh/innisfree/serum/innisfree-serum-duong-am-da-tra-xanh-1.webp'),(61,'Son Dưỡng Ẩm Môi Chiết Xuất Mật Ong Hoa Cải Innisfree Canola Honey Lip Balm 3.5g',1,7,'Son dưỡng môi Innisfree Canola Honey chứa mật ong nguyên chất từ hoa cải đảo Jeju và dầu hạt cải, cung cấp độ ẩm sâu giúp đôi môi luôn mềm mại, cải thiện sắc tố môi hồng hào tự nhiên.','[\"Dưỡng ẩm sâu và trị nứt nẻ, bong tróc môi tức thì\", \"Cung cấp vitamin và dưỡng chất giúp môi hồng hào mềm mịn\", \"Làm lớp lót dưỡng môi trước khi thoa son màu\"]','[\"Mật ong hoa cải Jeju Canola Honey\", \"Dầu hạt cải hữu cơ\", \"Sáp ong tự nhiên\", \"Bơ xoài\"]','Thoa trực tiếp lên môi bất cứ khi nào cảm thấy khô, hoặc thoa lớp dày trước khi đi ngủ làm mặt nạ ngủ cho môi.','chamsocda-anh/innisfree/son-duong/innisfree-son-duong-1.jpg'),(62,'Sữa Rửa Mặt Cấp Ẩm Trà Xanh Innisfree Green Tea Hydrating Amino Acid Foam 150g',3,7,'Sữa rửa mặt trà xanh Innisfree chứa nước trà xanh tươi Beauty Green Tea dồi dào axit amin và phức hợp Amino Acid Complex tạo lớp bọt xốp dày đặc, làm sạch bụi bẩn mà vẫn để lại lớp màng ẩm mềm mướt.','[\"Làm sạch sâu bụi bẩn, bã nhờn mà không gây cảm giác khô căng kít\", \"Cung cấp độ ẩm dồi dào từ trà xanh và phức hợp axit amin\", \"Lớp bọt xốp siêu mịn giảm thiểu lực ma sát gây hại cho da\"]','[\"Nước trà xanh Beauty Green Tea\", \"Phức hợp Amino Acid Complex\", \"Chiết xuất rễ trà xanh\"]','Lấy lượng sản phẩm cỡ hạt đậu ra tay ướt, tạo bọt thật bông và mát-xa khắp mặt rồi rửa sạch với nước ấm.','chamsocda-anh/innisfree/sua-rua-mat/sua-rua-mat-innisfree-duong-am-chiet-xuat-tra-xanh-150g/innisfree-sua-rua-mat-duong-am-01.webp'),(63,'Sữa Rửa Mặt Tro Núi Lửa BHA Làm Sạch Sâu Kiềm Nhờn Innisfree Volcanic BHA Foam 150g',3,7,'Sữa rửa mặt tro núi lửa Innisfree thế hệ mới bổ sung thành phần BHA giúp hòa tan sợi bã nhờn, làm thông thoáng lỗ chân lông và kiểm soát dầu thừa hiệu quả cho làn da dầu mụn.','[\"Hút sạch dầu thừa và bụi bẩn tích tụ với tro núi lửa xốp\", \"BHA thẩm thấu làm sạch tế bào chết và sợi bã nhờn trong nang lông\", \"Ngăn ngừa hình thành mụn đầu đen và mụn cám\"]','[\"Tro núi lửa Jeju Volcanic Clusters\", \"BHA (Salicylic Acid)\", \"Nước khoáng núi lửa\"]','Tạo bọt với nước, xoa bóp kỹ vùng chữ T và cánh mũi trong 1 phút rồi rửa lại bằng nước sạch.','chamsocda-anh/innisfree/sua-rua-mat/sua-rua-mat-innisfree-kiem-soat-nhon-nui-lua-bha/innisfree-sua-rua-mat-kiem-nhon-1.jpg'),(64,'Sữa Rửa Mặt Sáng Da Mờ Thâm Se Khít Lỗ Chân Lông Innisfree Brightening Cleanser',3,7,'Sữa rửa mặt sáng da Innisfree chiết xuất từ vỏ quýt Hallabong đảo Jeju chứa hàm lượng Vitamin C cao, kết hợp bọt kem mềm mại giúp da sạch bóng, rạng rỡ và thu nhỏ lỗ chân lông.','[\"Làm sạch sâu và cải thiện sắc tố da sạm màu trở nên sáng rỡ\", \"Thu nhỏ và làm mịn bề mặt lỗ chân lông\", \"Mùi hương cam quýt tự nhiên sảng khoái và tươi mát\"]','[\"Chiết xuất vỏ quýt Hallabong Jeju\", \"Dẫn xuất Vitamin C, B3, B5\", \"Hyaluronic Acid\"]','Lấy lượng kem vừa đủ tạo bọt với nước, thoa đều lên da mặt ướt và rửa sạch lại.','chamsocda-anh/innisfree/sua-rua-mat/sua-rua-mat-innisfree-sachj-sau-sang-da-diu-nhe/innisfree-sua-rua-mat-sach-sang-diu-1.jpg'),(65,'Nước Hoa Hồng Cân Bằng Ẩm Trà Xanh Innisfree Green Tea Balancing Skin EX 200ml',4,7,'Nước hoa hồng trà xanh Innisfree Green Tea Balancing Skin EX kết cấu dạng lỏng sánh nhẹ, thẩm thấu nhanh phục hồi lượng ẩm đã mất sau khi rửa mặt, cân bằng tỷ lệ dầu - nước hoàn hảo cho da.','[\"Cân bằng độ ẩm và độ pH chuẩn cho da ngay sau bước làm sạch\", \"Kiểm soát lượng dầu thừa vùng chữ T mà vẫn cấp đủ ẩm vùng chữ U\", \"Cho làn da cảm giác sảng khoái, mềm mướt và tươi sáng\"]','[\"Trà xanh Beauty Green Tea 16 loại acid amin\", \"Betaine\", \"Glycerin thực vật\"]','Thấm một lượng vừa đủ ra bông tẩy trang hoặc đổ ra lòng bàn tay rồi vỗ nhẹ khắp mặt và cổ.','chamsocda-anh/innisfree/toner/innisfree-toner-cap-am-phuc-hoi-15ml-1.jpg'),(66,'Kem Chống Nắng Dưỡng Sáng Mờ Thâm Laneige Radian-C Sun Cream SPF 50+ PA++++ 50ml',2,10,'Kem chống nắng dưỡng sáng Laneige Radian-C Sun Cream tích hợp công nghệ độc quyền bảo vệ da 360 độ trước tia UVA, UVB và cả ánh sáng xanh, đồng thời bổ sung dẫn xuất Vitamin C EAE giúp mờ đốm nâu sắc tố.','[\"Chống nắng phổ rộng bảo vệ da tối ưu trước tia UV và ánh sáng xanh màn hình\", \"Dưỡng sáng da và làm mờ các đốm thâm nám sạm màu\", \"Chất kem ẩm mịn, thoáng nhẹ tệp vào da như kem dưỡng\"]','[\"Dẫn xuất Vitamin C ổn định (EAE)\", \"Melasolv (hoạt chất độc quyền làm sáng)\", \"Ceramide bảo vệ da\"]','Thoa đều lên toàn bộ khuôn mặt vào buổi sáng trước khi ra ngoài 20 phút.','chamsocda-anh/laneige/kem-chong-nang/laneige-kem-chong-nang-01.webp'),(67,'Kem Dưỡng Sáng Da Mờ Vết Thâm Căng Mọng Laneige Radian-C Cream 50ml',5,10,'Kem dưỡng sáng da Laneige Radian-C Cream chứa 8.5% dẫn xuất Vitamin C EAE đậm đặc và hoạt chất Melasolv được cấp bằng sáng chế, làm mờ đốm thâm vi mô chỉ sau 3 ngày mà hoàn toàn không gây kích ứng.','[\"Làm mờ vết thâm mụn và đốm nâu sạm màu sau 3 ngày\", \"Tăng cường độ sáng rạng rỡ và đều màu da rõ rệt\", \"Công thức dịu nhẹ không gây châm chích, an toàn cho cả da nhạy cảm\"]','[\"8.5% Vitamin C Derivative (EAE)\", \"Melasolv độc quyền Amorepacific\", \"Vitamin E tinh khiết\"]','Lấy lượng kem vừa đủ thoa đều từ trong ra ngoài theo chiều cấu tạo da mỗi sáng và tối.','chamsocda-anh/laneige/kem-duong-am/kem-duong-am-sang-da-mo-tham/laneige-kem-duong-sang-da-mo-tham-01.webp'),(68,'Kem Dưỡng Mắt Giảm Quầng Thâm Bọng Mắt Laneige Water Bank Blue Hyaluronic Eye Cream 25ml',12,10,'Kem dưỡng mắt Laneige Water Bank Blue Hyaluronic Eye Cream chứa phân tử Blue HA siêu nhỏ thẩm thấu gấp 2000 lần và Caffeine, giúp xóa tan vẻ mệt mỏi, giảm sưng bọng mắt và mờ quầng thâm tức thì.','[\"Giảm sưng bọng mắt và làm mờ quầng thâm mắt mệt mỏi do thiếu ngủ\", \"Cấp ẩm sâu làm mờ các nếp nhăn và rãnh nhăn li ti quanh khóe mắt\", \"Kết cấu kem mát lạnh làm dịu vùng da mắt nhạy cảm\"]','[\"Blue Hyaluronic Acid siêu phân tử nano\", \"Caffeine kích thích tuần hoàn\", \"Glutathione chống oxy hóa\"]','Dùng ngón tay áp út chấm nhẹ kem lên vùng da dưới mắt và mí mắt trên, vỗ nhẹ từ khóe mắt ra đuôi mắt.','chamsocda-anh/laneige/kem-duong-am/kem-duong-am-vung-mat/laneige-kem-duong-am-vung-mat-01.webp'),(69,'Kem Dưỡng Chống Lão Hóa Cải Thiện Nếp Nhăn Laneige Perfect Renew 3X Cream 50ml',5,10,'Kem chống lão hóa cao cấp Laneige Perfect Renew 3X Cream sở hữu công nghệ 3X™ kết hợp Retinol, Peptide và Flavonoid, tác động mạnh mẽ vào 3 vấn đề lão hóa chính: nếp nhăn, độ đàn hồi và mật độ da.','[\"Cải thiện 60% nếp nhăn sâu trên trán, khóe miệng và rãnh cười\", \"Nâng cơ và phục hồi độ săn chắc, căng bóng đàn hồi cho da\", \"Tăng sinh collagen và mật độ tế bào biểu bì chỉ sau 4 tuần\"]','[\"3X Retinol thế hệ mới\", \"Phức hợp Peptide 21.5%\", \"Gừng đỏ Bio-Flavonoid\"]','Thoa kem lên mặt và cổ vào bước cuối của chu trình dưỡng da buổi tối, mát-xa nhẹ nhàng theo chiều nâng cơ.','chamsocda-anh/laneige/kem-duong-am/kem-duong-ngan-ngua-lao-hoa/laneige-kem-duong-ngan-ngua-lao-hoa-02.webp'),(70,'Kem Lót Nâng Tông Hiệu Chỉnh Đỏ Da Laneige Skin Veil Base EX No.60 Mint Green 30ml',10,10,'Kem lót Laneige Skin Veil Base EX màu xanh bạc hà số 60 là bí quyết che khuyết điểm da ửng đỏ, mụn sưng và đốm đỏ hoàn hảo, đồng thời dưỡng ẩm và bảo vệ da trước ánh sáng xanh và tia UV.','[\"Hiệu chỉnh màu da, triệt tiêu sắc tố đỏ do mụn hoặc dị ứng\", \"Tạo lớp nền mỏng mịn ngậm nước, giữ lớp makeup lâu trôi suốt 12h\", \"Chống nắng SPF 28 PA++ và màng lọc bụi mịn bảo vệ da\"]','[\"Bột màu khoáng xanh bạc hà\", \"Tinh chất lựu đỏ chống oxy hóa\", \"Acai Berry dưỡng sáng\"]','Lấy lượng kem lót cỡ hạt đậu chấm lên các điểm trên mặt sau bước kem chống nắng, tán đều trước khi đánh kem nền.','chamsocda-anh/laneige/kem-duong-am/kem-lot-duong-am-va-nang-tong-laneige-skin-veil-base-ex-no-60-mint-green-30ml/laneige-kem-duong-am-nang-tong-2.webp'),(71,'Mặt Nạ Ngủ Cấp Nước Phục Hồi Da Đêm Laneige Water Sleeping Mask EX 70ml',7,10,'Mặt nạ ngủ cấp nước bán chạy nhất thế giới của Laneige chứa 23.8 tỷ lợi khuẩn Pro-biotics Complex và Squalane, giúp phục hồi và tái tạo hệ vi sinh vật của da sau một đêm say giấc nồng.','[\"Cấp nước dồi dào, đánh thức làn da căng bóng ngậm nước vào sáng hôm sau\", \"Cân bằng hệ vi sinh da, tăng cường sức đề kháng cho màng ẩm\", \"Công nghệ Sleepscent độc quyền đem lại giấc ngủ sâu thư giãn\"]','[\"Sleeping Micro Biome™ (23.8 tỷ men vi sinh)\", \"Squalane thực vật\", \"Trehalose\"]','Sử dụng vào buổi tối 2-3 lần/tuần sau các bước dưỡng da. Để nguyên mặt nạ đi ngủ và rửa sạch lại vào sáng hôm sau.','chamsocda-anh/laneige/mat-na-ngu/mat-na-ngu-duong-am/laneige-mat-na-ngu-duong-am-01.webp'),(72,'Mặt Nạ Ngủ Tăng Sinh Collagen Săn Chắc Da Laneige Bouncy & Firm Sleeping Mask 60ml',7,10,'Mặt nạ ngủ đàn hồi thế hệ mới Laneige Bouncy & Firm chứa 50.000 hạt viên nang Collagen và phức hợp hoa mẫu đơn, giúp làn da căng mọng, đàn hồi và săn chắc tràn đầy sức sống chỉ sau một đêm.','[\"Tăng sinh độ đàn hồi và săn chắc cho làn da chùng nhão\", \"Hạt nang collagen tan chảy cấp ẩm sâu và làm đầy rãnh nhăn\", \"Cho làn da độ căng bóng mịn màng và rạng rỡ vào mỗi buổi sáng\"]','[\"Peony & Collagen Complex™\", \"50.000 hạt Hydro-Melt Glow Capsules\", \"Peptide đàn hồi\"]','Thoa đều lớp mặt nạ lên mặt trước khi đi ngủ, thư giãn và rửa sạch lại vào sáng hôm sau.','chamsocda-anh/laneige/mat-na-ngu/mat-na-tang-colagen-san-chac-da/laneige-mat-na-tang-cuong-colagen-01.jpg'),(73,'Sữa Rửa Mặt Cấp Ẩm Dịu Nhẹ Laneige Water Bank Blue Hyaluronic Cleansing Foam 150g',3,10,'Sữa rửa mặt Laneige Water Bank Blue Hyaluronic tạo lớp bọt dày xốp mềm mịn chứa các hạt Cellulose tan chảy và enzyme papain, nhẹ nhàng làm sạch cặn trang điểm và bụi bẩn mà vẫn giữ da ẩm mịn.','[\"Làm sạch sâu tạp chất và cặn bã trong lỗ chân lông\", \"Hạt cellulose tự nhiên tẩy tế bào chết siêu dịu nhẹ\", \"Blue Hyaluronic Acid khóa ẩm không gây căng rát sau khi rửa\"]','[\"Blue Hyaluronic Acid nano\", \"Hạt siêu nhỏ Cellulose tan chảy\", \"Enzyme đu đủ Papain\"]','Tạo bọt với nước trên tay ướt, nhẹ nhàng mát-xa toàn bộ khuôn mặt rồi rửa sạch lại bằng nước ấm.','chamsocda-anh/laneige/sua-rua-mat/laneige-sua-rua-mat-01.webp'),(74,'Nước Cân Bằng Dưỡng Ẩm Phục Hồi Laneige Water Bank Blue Hyaluronic Toner 160ml',4,10,'Nước hoa hồng dưỡng ẩm sâu Laneige Water Bank Blue Hyaluronic thẩm thấu nhanh chóng vào các lớp biểu bì, xoa dịu làn da mệt mỏi thiếu nước và mở đường cho các bước dưỡng thẩm thấu tốt hơn.','[\"Cấp ẩm tức thì 140% cho da khô mất nước\", \"Phục hồi màng bảo vệ da suy yếu do khói bụi ô nhiễm\", \"Kết cấu tươi mát, không gây bết dính trên da\"]','[\"Blue Hyaluronic Acid\", \"Chiết xuất nấm men Beta-Glucan\", \"Panthenol\"]','Thoa đều lên mặt sau bước rửa mặt, vỗ nhẹ nhàng cho dưỡng chất thấm sâu.','chamsocda-anh/laneige/toner/laneige-toner-01.jpg'),(75,'Kem Dưỡng Phục Hồi Làm Dịu Kích Ứng La Roche-Posay Cicaplast Baume B5+ 40ml/100ml',5,9,'Kem dưỡng phục hồi đa năng La Roche-Posay Cicaplast Baume B5+ công thức cải tiến bổ sung phức hợp men vi sinh Tribioma kết hợp 5% Panthenol và Madecassoside, giúp làm dịu và phục hồi da tổn thương chỉ sau 1 giờ.','[\"Làm dịu tức thì tình trạng kích ứng, bỏng rát, ngứa ngáy và mẩn đỏ\", \"Phục hồi màng ẩm bảo vệ da nhanh chóng sau 1 giờ sử dụng\", \"Kháng khuẩn, ngăn ngừa để lại sẹo và vết thâm sau mụn\"]','[\"5% Panthenol (Vitamin B5)\", \"Madecassoside (tinh chất rau má)\", \"Hệ vi sinh Tribioma độc quyền\", \"Kẽm & Mangan kháng khuẩn\"]','Thoa 2 lần/ngày lên vùng da đã được làm sạch và lau khô. Có thể dùng cho mặt, môi và toàn thân.','chamsocda-anh/laroche-posay/duong-am/laroche-kem-duong-am-03.jpg'),(76,'Kem Chống Nắng Kiểm Soát Dầu La Roche-Posay Anthelios UVmune 400 Oil Control Gel-Cream 50ml',2,9,'Kem chống nắng kiểm soát dầu số 1 của La Roche-Posay tích hợp màng lọc độc quyền Mexoryl 400 chống lại tia UVA dài độc hại nhất (380-400nm) và hoạt chất Airlicium kiềm dầu suốt 12 giờ.','[\"Bảo vệ da tối đa trước tia UVA dài nguy hiểm gây sạm nám và lão hóa sâu\", \"Hoạt chất Airlicium hấp thụ bã nhờn, kiềm dầu khô ráo suốt 12h\", \"Kháng nước, kháng mồ hôi, không cay mắt và không để lại vệt trắng\"]','[\"Màng lọc Mexoryl 400 độc quyền\", \"Hoạt chất kiềm dầu Airlicium\", \"Nước khoáng La Roche-Posay\"]','Thoa kem trước khi tiếp xúc với ánh nắng 20 phút. Thoa lại sau mỗi 2 giờ nếu hoạt động ngoài trời.','chamsocda-anh/laroche-posay/kem-chong-nang/laroche-kem-chong-nang-1.webp'),(77,'Kem Giảm Mụn Mờ Thâm Tái Phát Mới La Roche-Posay Effaclar Duo+M 40ml',5,9,'Kem giảm mụn thế hệ mới La Roche-Posay Effaclar Duo+M với hoạt chất Phylobioma đột phá nhắm thẳng vào vi khuẩn gây mụn C.acnes type IA1, giảm mụn rõ rệt chỉ sau 8 giờ và ngăn ngừa thâm mụn kéo dài.','[\"Giảm sưng viêm mụn mủ, mụn bọc rõ rệt chỉ sau 8 giờ\", \"Ngăn ngừa hình thành vết thâm sau mụn và chống tái phát mụn hiệu quả\", \"Thông thoáng lỗ chân lông, điều tiết lượng bã nhờn dư thừa\"]','[\"Phylobioma độc quyền\", \"Procerad ngừa thâm\", \"Niacinamide\", \"LHA & Salicylic Acid\"]','Thoa một lượng kem nhỏ lên toàn mặt hoặc chấm trực tiếp lên các nốt mụn vào buổi sáng và tối sau bước làm sạch.','chamsocda-anh/laroche-posay/kem-tri-mun/laroche-posay-kem-tri-mun-1.jpg'),(78,'Nước Tẩy Trang Kiểm Soát Dầu Cho Da Dầu Mụn La Roche-Posay Effaclar Micellar Water Ultra 400ml',6,9,'Nước tẩy trang La Roche-Posay Effaclar Micellar Water Ultra chứa các hạt Micelle kết hợp kẽm PCA giúp làm sạch 99% lớp trang điểm và bụi mịn PM 2.5 mà không làm khô da, kiểm soát dầu nhờn hiệu quả.','[\"Làm sạch 99% lớp nền trang điểm và 70% mascara chỉ với bông đầu tiên\", \"Kẽm PCA kiểm soát dầu thừa và giảm bóng nhờn cho da dầu mụn\", \"Nước khoáng La Roche-Posay giàu khoáng chất xoa dịu kích ứng\"]','[\"Công nghệ Glyco Micellar\", \"Kẽm PCA (Zinc PCA)\", \"Nước khoáng La Roche-Posay\"]','Thấm ướt bông cotton, nhẹ nhàng lau khắp mặt và cổ. Không cần rửa lại với nước.','chamsocda-anh/laroche-posay/nuoc-tay-trang/laroche-posay-nuoc-tay-trang-01.webp'),(79,'Dưỡng Chất Cấp Ẩm Tái Tạo Săn Chắc Da La Roche-Posay Hyalu B5 Serum 30ml',4,9,'Dưỡng chất phục hồi da Hyalu B5 Serum của La Roche-Posay kết hợp 2 loại Hyaluronic Acid nguyên chất cùng Vitamin B5 và Madecassoside, giúp làm đầy rãnh nhăn, tái tạo làn da căng mọng và phục hồi màng ẩm sau 4 giờ.','[\"Cấp nước tầng sâu, làm đầy rãnh nhăn nông và tăng độ đàn hồi cho da\", \"Tái tạo và phục hồi hàng rào bảo vệ da bị tổn thương sau 4 giờ\", \"Làn da trở nên căng mọng, mềm mượt và tươi trẻ tức thì\"]','[\"Hyaluronic Acid 2 kích thước phân tử\", \"5% Vitamin B5 (Panthenol)\", \"Madecassoside\"]','Nhỏ 3-4 giọt serum lên mặt và cổ, vỗ nhẹ nhàng vào mỗi sáng và tối trước bước kem dưỡng ẩm.','chamsocda-anh/laroche-posay/serum-phuc-hoi-da/laroche-posay-serum-phuc-hoi-da-1.jpg'),(80,'Gel Rửa Mặt Tạo Bọt Cho Da Dầu Nhạy Cảm La Roche-Posay Effaclar Purifying Foaming Gel 400ml',3,9,'Gel rửa mặt tạo bọt La Roche-Posay Effaclar Gel làm sạch sâu bụi bẩn và bã nhờn dư thừa với độ pH 5.5 hoàn hảo, chứa Kẽm PCA kiềm dầu và nước khoáng xoa dịu da nhạy cảm.','[\"Làm sạch sâu nhẹ nhàng, thanh lọc bã nhờn mà không làm khô căng da\", \"Kiềm dầu và giảm bóng nhờn rõ rệt sau khi rửa\", \"Độ pH 5.5 lý tưởng bảo vệ lớp màng axit tự nhiên của da\"]','[\"Kẽm PCA (Zinc PCA)\", \"Nước khoáng nhiệt La Roche-Posay\", \"Gốc làm sạch dịu nhẹ không xà phòng\"]','Tạo bọt với nước trong lòng bàn tay, mát-xa nhẹ nhàng khắp mặt trong 1 phút rồi rửa sạch lại với nước.','chamsocda-anh/laroche-posay/sua-rua-mat/sua-rua-mat-da-dau/laroche-posay-sua-rua-mat-da-dau-1.webp'),(81,'Sữa Rửa Mặt Sáng Da Mờ Vết Thâm La Roche-Posay Pure Niacinamide 10 Cleanser 200ml',3,9,'Sữa rửa mặt sáng da mờ thâm La Roche-Posay Pure Niacinamide 10 kết hợp Niacinamide tinh khiết và bọt kem dịu nhẹ, giúp loại bỏ bụi bẩn, cải thiện đốm sắc tố và làm đều màu da ngay từ bước làm sạch.','[\"Hỗ trợ làm mờ các vết thâm nám, thâm mụn sạm màu\", \"Làm sạch sâu êm dịu, không gây cảm giác khô rát\", \"Dưỡng da sáng khỏe, rạng rỡ và đều màu hơn từng ngày\"]','[\"Niacinamide tinh khiết\", \"Glycerin cấp ẩm\", \"Nước khoáng làm dịu\"]','Tạo bọt và rửa mặt hàng ngày vào mỗi sáng và tối.','chamsocda-anh/laroche-posay/sua-rua-mat/sua-rua-mat-da-tham/laroche-posay-sua-rua-mat-tham-1.png'),(82,'Gel Rửa Mặt Vi Sinh Giảm Mụn Toàn Thân La Roche-Posay Effaclar Micro-Peeling Purifying Gel 400ml',3,9,'Gel rửa mặt và tắm giảm mụn La Roche-Posay Micro-Peeling chứa 2% Salicylic Acid và LHA giúp tẩy tế bào chết vi mô, điều trị mụn lưng, mụn ngực và mụn ẩn sần sùi trên mặt hiệu quả.','[\"2% Salicylic Acid (BHA) giải phóng bít tắc lỗ chân lông sâu\", \"Giảm mụn viêm, mụn cám và mụn lưng, mụn ngực hiệu quả rõ rệt\", \"Tẩy tế bào chết bề mặt giúp da láng mịn không còn sần sùi\"]','[\"2% Salicylic Acid (BHA)\", \"LHA (Lipo-Hydroxy Acid)\", \"Kẽm PCA\"]','Tạo bọt và thoa lên vùng da mặt hoặc vùng lưng/ngực bị mụn, mát-xa 1-2 phút rồi xả sạch.','chamsocda-anh/laroche-posay/sua-rua-mat/sua-rua-mat-giam-mun/laroche-posay-sua-rua-mat-giam-mun-1.jpg'),(83,'Kem Chống Nắng Khoáng Chất Vật Lý The Ordinary Mineral UV Filters SPF 30 With Antioxidants 50ml',2,16,'Kem chống nắng vật lý thuần khoáng The Ordinary Mineral UV Filters SPF 30 chứa Zinc Oxide và Titanium Dioxide vi hạt, kết hợp phức hợp chống oxy hóa và Bio-Sugar Complex bảo vệ da toàn diện khỏi tia UV và gốc tự do.','[\"Bảo vệ da vật lý quang phổ rộng với Zinc Oxide không nano\", \"Phức hợp chống oxy hóa ngăn ngừa lão hóa sớm do ánh nắng\", \"Công thức dịu nhẹ không gây kích ứng cho da sau xâm lấn\"]','[\"Zinc Oxide & Titanium Dioxide\", \"Bio-Active Antioxidant Network\", \"Bio-Sugar Complex cấp ẩm\"]','Thoa đều lên mặt trước khi ra ngoài trời 15-20 phút.','chamsocda-anh/the-ordinary/kem-chong-nang/the-ordinary-kem-chong-nang-01.jpg'),(84,'Kem Dưỡng Ẩm Tự Nhiên The Ordinary Natural Moisturizing Factors + HA 100ml',5,16,'Kem dưỡng ẩm The Ordinary NMF + HA chứa các thành phần mô phỏng màng dưỡng ẩm tự nhiên của da (11 axit amin, phospholipid, triglyceride, ceramide và HA), khóa ẩm bền vững mà không gây nhờn bóng.','[\"Cung cấp màng dưỡng ẩm tự nhiên NMF tức thì và lâu dài\", \"Chất kem mịn xốp, thấm ráo không để lại cảm giác nhờn dính\", \"Phục hồi độ đàn hồi và làm mềm da khô căng thiếu ẩm\"]','[\"11 loại Axit Amin\", \"Ceramides & Phospholipids\", \"Hyaluronic Acid\", \"Glycerin & Urea\"]','Thoa lên da mặt vào buổi sáng và tối sau các bước serum.','chamsocda-anh/the-ordinary/kem-duong/kem-duong-am-mem-da/the-ordinary-duong-am-01.jpg'),(85,'Kem Dưỡng Sáng Da Mờ Nám The Ordinary Vitamin C Suspension 23% + HA Spheres 2% 30ml',5,16,'Kem dưỡng sáng da The Ordinary chứa hàm lượng cực cao 23% L-Ascorbic Acid nguyên chất dạng hạt phân tán không chứa nước, giúp dưỡng trắng bật tông, mờ nám sạm và chống lão hóa đỉnh cao.','[\"Nồng độ 23% Vitamin C nguyên chất cho hiệu quả sáng da mờ thâm nám tối đa\", \"Hạt HA Spheres cấp nước giữ da mềm mại và giảm châm chích\", \"Kích thích tăng sinh collagen làm mờ nếp nhăn và trẻ hóa da\"]','[\"23% L-Ascorbic Acid nguyên chất\", \"2% Hyaluronic Acid Spheres dạng viên nang\"]','Dùng một lượng nhỏ bằng hạt đậu vào buổi tối. Có thể trộn với kem dưỡng NMF để giảm cảm giác châm chích ban đầu.','chamsocda-anh/the-ordinary/kem-duong/kem-duong-trang-nang-tone/the-ordinary-duong-trang-01.jpg'),(86,'Mặt Nạ Đất Sét Hút Dầu Giảm Mụn The Ordinary Salicylic Acid 2% Masque 50ml',7,16,'Mặt nạ The Ordinary Salicylic Acid 2% Masque kết hợp than hoạt tính, đất sét Amazon và 2% BHA, làm sạch sâu bã nhờn, đánh bay mụn đầu đen và đem lại làn da sáng mịn rạng rỡ.','[\"2% BHA hòa tan bã nhờn và tế bào chết tắc nghẽn trong lỗ chân lông\", \"Than hoạt tính và đất sét hút sạch độc tố và tạp chất bề mặt\", \"Giảm rõ rệt mụn cám, mụn đầu đen và se khít lỗ chân lông\"]','[\"2% Salicylic Acid (BHA)\", \"Than hoạt tính (Charcoal Powder)\", \"Đất sét Amazon (Kaolin & Squalane)\"]','Đắp một lớp mỏng lên da khô sạch trong tối đa 10 phút, sau đó rửa sạch bằng nước ấm. Dùng 1 lần/tuần vào buổi tối.','chamsocda-anh/the-ordinary/mat-na/the-ordinary-mat-na-01.jpg'),(87,'Tinh Chất Giảm Mụn Ẩn The Ordinary Salicylic Acid 2% Anhydrous Solution 30ml',4,16,'Tinh chất The Ordinary Salicylic Acid 2% dạng không chứa nước (Anhydrous) với nền Squalane làm dịu, giải phóng BHA từ từ giúp đẩy mụn ẩn, gom cồi mụn mà không gây bong tróc hay khô rát da.','[\"Đẩy mụn ẩn, thông thoáng lỗ chân lông và giảm mụn đầu đen\", \"Nền Squalane dưỡng ẩm làm dịu, giảm thiểu tối đa kích ứng của BHA\", \"Làm mịn kết cấu bề mặt da sần sùi\"]','[\"2% Salicylic Acid (BHA)\", \"Squalane tự nhiên làm dịu\"]','Thoa 1-2 giọt lên vùng da cần điều trị vào buổi tối sau bước làm sạch và trước kem dưỡng.','chamsocda-anh/the-ordinary/serum-cham-da/dieu-tri-mun-an/the-ordinary-serum-tri-mun-an-01.jpg'),(88,'Tinh Chất Cấp Ẩm Phục Hồi Quốc Dân The Ordinary Hyaluronic Acid 2% + B5 30ml',4,16,'Serum cấp ẩm phục hồi bán chạy nhất của The Ordinary kết hợp 3 kích thước phân tử Hyaluronic Acid và Pro-Vitamin B5, giúp cấp nước đa tầng biểu bì và đẩy nhanh quá trình phục hồi tế bào da tổn thương.','[\"Cấp ẩm đa tầng biểu bì cho làn da căng mọng, ngậm nước\", \"Vitamin B5 làm dịu và phục hồi da nhạy cảm, giảm đỏ rát\", \"Tăng cường độ mềm mại và đàn hồi của làn da thiếu nước\"]','[\"2% Hyaluronic Acid (đa phân tử)\", \"Vitamin B5 (Panthenol)\", \"Ahnfeltia Concinna Extract\"]','Nhỏ 3-4 giọt lên da mặt ẩm sau bước làm sạch và toner, vỗ nhẹ cho tinh chất thẩm thấu trước khi bôi kem khóa ẩm.','chamsocda-anh/the-ordinary/serum-cham-da/duong-am-phuc-hoi/the-ordinary-serum-duong-am-phuc-hoi-01.webp'),(89,'Tinh Chất Chống Lão Hóa Đa Năng The Ordinary Multi-Peptide + HA Serum (Buffet) 30ml',4,16,'Serum chống lão hóa \"tiệc Buffet\" trứ danh của The Ordinary quy tụ 5 phức hợp peptide công nghệ cao (Matrixyl, Syn-Ake, Relistase, Argirelox) cùng Hyaluronic Acid, tấn công cùng lúc nhiều dấu hiệu lão hóa da.','[\"Làm mờ nếp nhăn tĩnh và nếp nhăn động quanh mắt, khóe miệng\", \"Kích thích sản sinh collagen, cải thiện độ đàn hồi và săn chắc\", \"Cấp ẩm sâu giúp da căng bóng trẻ trung rạng rỡ\"]','[\"Matrixyl 3000 & Matrixyl Synthe 6\", \"Syn-Ake peptide\", \"Argirelox peptide\", \"Phức hợp Probiotic và HA\"]','Thoa vài giọt khắp mặt vào buổi sáng và buổi tối trước các loại kem dưỡng.','chamsocda-anh/the-ordinary/serum-cham-da/ngan-ngua-lao-hoa/the-ordinary-serum-ngua-lao-hoa-01.jpg'),(90,'Tinh Chất Giảm Mụn Mờ Thâm Kiềm Dầu The Ordinary Niacinamide 10% + Zinc 1% 30ml',4,16,'Serum kiềm dầu và mờ thâm mụn bán chạy nhất toàn cầu chứa 10% Niacinamide nguyên chất và 1% muối kẽm PCA, kiểm soát triệt để hoạt động của tuyến bã nhờn, làm dịu mụn viêm và mờ vết thâm sau mụn.','[\"Kiểm soát bã nhờn, giảm bóng dầu và se khít lỗ chân lông\", \"Làm mờ vết thâm đỏ, thâm đen sau mụn và dưỡng đều màu da\", \"Kháng viêm, làm dịu các nốt mụn sưng đỏ\"]','[\"10% Niacinamide (Vitamin B3)\", \"1% Kẽm PCA (Zinc PCA)\", \"Chiết xuất hạt me\"]','Thoa đều 2-3 giọt lên toàn mặt vào mỗi buổi sáng và tối trước khi thoa kem dưỡng ẩm.','chamsocda-anh/the-ordinary/serum-cham-da/ngua-mun/the-ordinary-serum-ngua-mun-01.jpg'),(91,'Serum Tẩy Tế Bào Chết Hóa Học Đỏ The Ordinary AHA 30% + BHA 2% Peeling Solution 30ml',8,16,'Serum peel da đỏ huyền thoại The Ordinary kết hợp 30% AHA (Glycolic, Lactic, Tartaric, Citric) và 2% BHA cùng quả tiêu Tasmania, tái tạo bề mặt da láng mịn như gương và làm sáng da thần tốc.','[\"Tẩy sạch tế bào sừng già cỗi bề mặt và bã nhờn sâu trong lỗ chân lông\", \"Cải thiện tông da sáng bật tông, mờ thâm sạm và sẹo mụn\", \"Làm mịn bề mặt da thô ráp sần sùi chỉ sau 10 phút\"]','[\"30% AHA tổng hợp\", \"2% Salicylic Acid (BHA)\", \"Chiết xuất tiêu Tasmanian làm dịu\", \"Hyaluronic Acid & Vitamin B5\"]','Chỉ dùng buổi tối trên da KHÔ HOÀN TOÀN. Thoa đều và giữ trên da TỐI ĐA 10 PHÚT rồi rửa sạch bằng nước ấm. Dùng 1 lần/tuần.','chamsocda-anh/the-ordinary/serum-cham-da/tay-te-bao-chet/the-ordinary-serum-tay-te-bao-chet-01.jpg'),(92,'Tinh Chất Dưỡng Trắng Mờ Thâm Nám The Ordinary Alpha Arbutin 2% + HA 30ml',4,16,'Serum dưỡng trắng The Ordinary chứa 2% Alpha Arbutin tinh khiết (mạnh gấp 10 lần Arbutin thường) kết hợp Hyaluronic Acid, ức chế enzyme Tyrosinase sản sinh hắc sắc tố Melanin, làm mờ nám tàn nhang hiệu quả.','[\"Làm mờ các đốm nâu, tàn nhang và vết thâm mụn cứng đầu\", \"Dưỡng da trắng sáng, đều màu và rạng rỡ từ bên trong\", \"Hyaluronic Acid cấp ẩm giữ da luôn mọng nước không bong tróc\"]','[\"2% Alpha Arbutin tinh khiết\", \"Hyaluronic Acid phân tử đa tầng\", \"Axit lactic\"]','Thoa vài giọt khắp mặt vào buổi sáng và buổi tối. Ban ngày cần kết hợp bôi kem chống nắng.','chamsocda-anh/the-ordinary/serum-cham-da/tri-nam/the-ordinary-serum-tri-nam-01.jpg'),(93,'Tinh Chất Giảm Quầng Thâm Bọng Mắt The Ordinary Caffeine Solution 5% + EGCG 30ml',12,16,'Serum mắt The Ordinary chứa 5% nồng độ Caffeine đậm đặc hòa quyện cùng hoạt chất EGCG tinh khiết chiết xuất từ lá trà xanh, giúp co mạch máu, giảm bọng mắt sưng to và xóa mờ quầng thâm mắt gấu trúc.','[\"Giảm bọng mắt sưng to và ứ đọng dịch quanh mắt do thức khuya\", \"Làm sáng và xóa mờ quầng thâm mắt rõ rệt sau 4 tuần\", \"Chống oxy hóa mạnh mẽ bảo vệ vùng da mắt mỏng manh\"]','[\"5% Caffeine đậm đặc\", \"EGCG chiết xuất từ trà xanh tinh khiết\", \"Hyaluronic Acid\"]','Mỗi lần dùng 1 giọt nhỏ mát-xa nhẹ nhàng quanh đường viền mắt vào mỗi sáng và tối.','chamsocda-anh/the-ordinary/serum-cham-da/vung-mat/the-ordinary-serum-duong-mat-01.jpg'),(94,'Nước Hoa Hồng Tẩy Da Chết Sáng Da The Ordinary Glycolic Acid 7% Toning Solution 240ml',4,16,'Nước hoa hồng The Ordinary Glycolic Acid 7% tẩy tế bào chết hóa học nhẹ nhàng hàng ngày, cải thiện độ rạng rỡ của làn da, làm sạch bã nhờn, mờ thâm và hỗ trợ điều trị viêm nang lông, thâm nách, thâm mông cực kỳ hiệu quả.','[\"Tẩy da chết dịu nhẹ giúp da sáng bóng, căng mọng và mờ thâm\", \"Cải thiện kết cấu da thô ráp trở nên mịn màng\", \"Đa năng: dùng cho mặt, làm sáng vùng nách, khuỷu tay và giảm mụn lưng\"]','[\"7% Glycolic Acid (AHA)\", \"Nước cất hoa hồng & hoa cúc\", \"Chiết xuất tiêu Tasmanian làm dịu\", \"Nhân sâm dưỡng da\"]','Sử dụng vào buổi tối sau bước rửa mặt. Thấm ra bông tẩy trang lau nhẹ khắp mặt và cổ (tránh mắt). Dùng 2-3 lần/tuần.','chamsocda-anh/the-ordinary/toner/the-ordinary-toner-01.jpg'),(95,'Phấn Má Hồng Mịn Lì Tự Nhiên 3CE Face Blush 5.5g',11,1,'Phấn má hồng 3CE Face Blush với các hạt phấn siêu vi nhuyễn mịn tiệp ngay vào da, mang lại đôi gò má ửng hồng trong trẻo, tự nhiên suốt cả ngày dài mà không hề bay màu hay vón cục.','[\"Hạt phấn siêu nhỏ mịn màng, kiểm soát bã nhờn nhẹ nhàng trên gò má\", \"Lên màu chuẩn xác chỉ sau một lần phẩy cọ, bám màu bền bỉ 8h\", \"Tông màu thời thượng chuẩn phong cách Hàn Quốc trẻ trung\"]','[\"Bột khoáng Talc siêu mịn\", \"Mica phát sáng tự nhiên\", \"Silica kiềm dầu\"]','Dùng cọ má hồng lấy một lượng phấn vừa đủ, phẩy nhẹ cọ để bay bớt bột thừa rồi dặm nhẹ nhàng lên gò má theo hướng chếch lên thái dương.','trangdiem-nuochoa/3ce/phan-3ce/phan-ma-hong-3ce-face-blush-5-5g/phan-3ce3.avif'),(96,'Phấn Má Hồng Bộ Sưu Tập Hoa Mùa Xuân 3CE Mood For Blossom Face Blush 5.5g',11,1,'Nằm trong bộ sưu tập Mood For Blossom lấy cảm hứng từ những cánh hoa mùa xuân đua nở, phấn má 3CE mang sắc hồng cam ngọt ngào, tạo hiệu ứng đôi má rạng rỡ và tràn đầy sức sống thanh xuân.','[\"Sắc hoa mùa xuân tươi tắn, tôn lên làn da sáng trong\", \"Khả năng khuếch tán ánh sáng tạo hiệu ứng gò má căng bóng mờ ảo\", \"Chất phấn êm nhẹ, không gây mốc hay bí tắc da\"]','[\"Bột phấn khoáng thiên nhiên\", \"Dầu dừa làm mềm hạt phấn\", \"Chất tạo màu an toàn\"]','Tán phấn nhẹ nhàng từ gò má xéo nhẹ ra mang tai để tạo khuôn mặt thon gọn và tươi tắn.','trangdiem-nuochoa/3ce/phan-3ce/phan-ma-hong-3ce-mood-for-blossom-face-blush-5-5g/phan-3ce1.avif'),(97,'Son Kem Lì Mờ Ảo Kháng Nước 3CE Blur Water Tint 4.6g - Tone Nâu Cam Đất',1,1,'Son kem 3CE Blur Water Tint với công thức dạng nước ẩm mượt khi mới thoa, sau vài giây sẽ chuyển thành lớp phủ mờ ảo như có màng filter, không lem dính ra khẩu trang hay ly cốc.','[\"Hiệu ứng làm mờ vân môi đỉnh cao, cho đôi môi mịn mượt như nhung\", \"Công thức chống lem chống trôi siêu việt, giữ màu bền suốt cả ngày\", \"Không gây khô tróc môi, cảm giác nhẹ tênh như không thoa son\"]','[\"Dimethicone làm mịn vân môi\", \"Nước khoáng cấp ẩm\", \"Chất gel mờ kháng lem\"]','Thoa một lượng son vừa phải vào lòng môi rồi bặm nhẹ lan đều ra viền môi. Đợi 10-15 giây để son set lại lớp finish mờ lì.','trangdiem-nuochoa/3ce/son-3ce/son-kem-li-3ce-blur-water-tint-4-6g-1/son-3ce3.avif'),(98,'Son Kem Lì 3CE Blur Water Tint 4.6g - Tone Đỏ Gạch Nâu Trầm Thời Thượng',1,1,'Tone màu đỏ gạch pha nâu trầm cực kỳ tôn da và trắng răng của dòng son 3CE Blur Water Tint, kết cấu mỏng nhẹ tựa làn nước đem lại đôi môi căng mịn, kiêu kỳ đầy cuốn hút.','[\"Tôn sáng mọi tông da, không làm xỉn men răng\", \"Lớp son tệp chặt vào môi, không bị loang lổ hay đóng cặn rãnh môi\", \"Bền màu 8-10 tiếng, thoải mái ăn uống nhẹ nhàng\"]','[\"Gel cấp ẩm Water-base\", \"Polyme khóa màu chống trôi\", \"Sắc tố khoáng đậm đặc\"]','Gạt bớt son ở miệng thỏi, thoa lòng môi tạo hiệu ứng ombre hoặc thoa toàn bộ môi cho vẻ đẹp sắc sảo.','trangdiem-nuochoa/3ce/son-3ce/son-kem-li-3ce-blur-water-tint-4-6g-2/son-3ce5.jpg'),(99,'Son Kem Lì Mịn Như Nhung Huyền Thoại 3CE Velvet Lip Tint 4g',1,1,'Dòng son kem lì nhung biểu tượng làm nên tên tuổi của 3CE với chất son xốp đặc mềm mượt như bơ, lướt êm ái trên môi và lấp đầy rãnh môi hoàn hảo, mang lại đôi môi quyến rũ khó cưỡng.','[\"Chất son kem nhung mịn xốp, lấp đầy mọi nếp nhăn môi\", \"Lên màu chuẩn sắc ngay từ lần quẹt cọ đầu tiên\", \"Chứa tinh dầu dưỡng không làm thâm hay khô tróc môi\"]','[\"Chiết xuất dầu hướng dương\", \"Dầu hoa cúc La Mã dưỡng ẩm\", \"Bột nhung tạo độ lì mịn\"]','Dùng đầu cọ vát lấy lượng son vừa đủ thoa đều từ lòng môi ra khóe môi.','trangdiem-nuochoa/3ce/son-3ce/son-kem-li-3ce-velvet-lip-tint-4g/son-3ce1.avif'),(100,'Nước Hoa Nữ Cao Cấp Chanel Allure Sensuelle Eau De Parfum 100ml',16,4,'Chanel Allure Sensuelle EDP mang hương thơm phương Đông nồng nàn đầy mê hoặc, kết hợp hương cam bergamot, hoa hồng Thổ Nhĩ Kỳ, hoắc hương và hổ phách vani, tạo nên dấu ấn quý phái, gợi cảm bất tận.','[\"Hương thơm phương Đông ấm áp, sang trọng và đầy ma lực quyến rũ\", \"Độ lưu hương cực đỉnh từ 8 - 12 giờ trên da và sợi vải\", \"Thiết kế chai thủy tinh vuông vức kinh điển của thương hiệu Chanel Paris\"]','[\"Hương đầu: Cam Bergamot, Tiêu hồng\", \"Hương giữa: Hoa hồng Thổ Nhĩ Kỳ, Hoa nhài\", \"Hương cuối: Hoắc hương, Hổ phách, Vanilla Bourbon\"]','Xịt lên các điểm mạch trên cơ thể như cổ tay, sau tai, hõm ngực để hương thơm lan tỏa quyến rũ nhất.','trangdiem-nuochoa/channel/nuoc-hoa/nuoc-hoa-nu-chanel-allure-sensuelle-edp-100ml/channel-hoa1.webp'),(101,'Nước Hoa Nữ Tươi Mát Chanel Chance Eau Fraiche Eau De Parfum 100ml',16,4,'Chanel Chance Eau Fraiche EDP mở ra làn gió tươi mát ngập tràn năng lượng với hương chanh thanh khiết, hoa nhài nồng nàn và gỗ tếch ấm áp, biểu tượng của sự may mắn và thanh lịch hiện đại.','[\"Hương thơm tươi mát, tràn đầy năng lượng tích cực và trẻ trung\", \"Hoàn hảo cho mùa xuân hè và môi trường văn phòng sang trọng\", \"Độ tỏa hương thanh lịch trong vòng một cánh tay\"]','[\"Hương đầu: Quả chanh vàng, Tuyết tùng\", \"Hương giữa: Hoa nhài, Lục bình, Tiêu hồng\", \"Hương cuối: Gỗ tếch, Xạ hương trắng, Hổ phách\"]','Xịt nhẹ nhàng lên quần áo và các điểm mạch đập để cảm nhận sự tươi mới suốt cả ngày.','trangdiem-nuochoa/channel/nuoc-hoa/nuoc-hoa-nu-chanel-chance-eau-fraiche-edp-spray-100ml/channel-hoa5.webp'),(102,'Nước Hoa Nữ Bí Ẩn Quyến Rũ Chanel Coco Noir Eau De Parfum 100ml',16,4,'Chanel Coco Noir với thiết kế thân chai đen tuyền huyền bí tượng trưng cho nét đẹp kiêu kỳ và quyền lực của người phụ nữ, mở đầu bằng bưởi chùm tươi tắn và chìm đắm trong hương gỗ đàn hương và đậu Tonka.','[\"Mùi hương đen huyền bí, quý phái dành riêng cho những buổi tiệc tối sang trọng\", \"Sự hòa quyện đỉnh cao giữa hương hoa hồng xứ Grasse và gỗ phương Đông\", \"Tỏa sáng khí chất tự tin, quyền uy và cuốn hút tuyệt đối\"]','[\"Hương đầu: Quả bưởi, Cam Bergamot\", \"Hương giữa: Hoa hồng, Hoa thủy tiên, Hoa phong lữ\", \"Hương cuối: Hoắc hương Indonesia, Đậu Tonka, Gỗ đàn hương\"]','Xịt vào gáy, cổ tay và xương quai xanh trước các buổi dạ tiệc hoặc sự kiện quan trọng.','trangdiem-nuochoa/channel/nuoc-hoa/nuoc-hoa-nu-chanel-coco-noir-eau-de-parfum-edp-100ml/channel-hoa3.webp'),(103,'Nước Hoa Biểu Tượng Thế Giới Chanel N°5 Eau De Parfum Limited Edition 100ml',16,4,'Phiên bản giới hạn Limited Edition của huyền thoại thế kỷ Chanel N°5, tượng trưng cho đỉnh cao nghệ thuật nước hoa Pháp với aldehyde lấp lánh hòa quyện cùng hoa hồng tháng Năm và hoa ngọc lan tây Grasse.','[\"Kiệt tác mùi hương kinh điển vượt thời gian được khao khát nhất lịch sử\", \"Phiên bản giới hạn với độ lưu hương sâu lắng và sang trọng vô song\", \"Giá trị sưu tầm cao dành cho các tín đồ yêu thích cái đẹp thượng lưu\"]','[\"Aldehyde phát sáng\", \"Hoa ngọc lan tây Ylang-Ylang\", \"Hoa hồng tháng Năm May Rose xứ Grasse\", \"Gỗ đàn hương & Vani\"]','Xịt nhẹ nhàng vào khoảng không phía trước rồi bước qua, hoặc chấm lên các điểm mạch đập cơ thể.','trangdiem-nuochoa/channel/nuoc-hoa/nuoc-hoa-nu-chanel-n-5-eau-de-parfum-limited-edition-100ml/channel-hoa10.webp'),(104,'Nước Hoa Nữ Huyền Thoại Chanel N°5 Eau De Parfum Spray 100ml',16,4,'Ra đời từ năm 1921 bởi Coco Chanel và Ernest Beaux, Chanel N°5 là định nghĩa của sự thanh lịch và xa xỉ đích thực, mùi hương của sự nữ tính tuyệt đối không thể nhầm lẫn.','[\"Mùi hương nữ tính quý phái biểu tượng của sự giàu có và tinh tế\", \"Tầng hương biến chuyển kỳ diệu theo thân nhiệt của người phụ nữ\", \"Lưu hương trên cơ thể trên 10 giờ\"]','[\"Hợp chất Aldehydes độc bản\", \"Tinh dầu hoa nhài Pháp\", \"Hoa huệ tây\", \"Hổ phách & Cỏ vetiver\"]','Xịt cách cơ thể 15-20cm lên cổ áo, sau gáy và cổ tay.','trangdiem-nuochoa/channel/nuoc-hoa/nuoc-hoa-nu-chanel-no5-edp-spray-100ml/channel-hoa7.webp'),(105,'Sữa Tắm Hương Nước Hoa Thượng Lưu Chanel Foaming Shower Gel 200ml',13,4,'Sữa tắm tạo bọt cao cấp Chanel biến phòng tắm thành spa xa xỉ kiểu Pháp, nhẹ nhàng làm sạch cơ thể, dưỡng ẩm mịn màng và ướp làn da trong hương thơm quý phái say đắm suốt nhiều giờ.','[\"Làm sạch êm dịu, giữ lại độ ẩm mượt nhung mềm trên da\", \"Ướp hương nước hoa Chanel sang trọng, thơm ngát khắp cơ thể\", \"Tạo lớp bọt xốp mịn màng nâng niu làn da sau ngày dài làm việc\"]','[\"Chiết xuất tinh dầu nước hoa Chanel nguyên chất\", \"Glycerin thực vật\", \"Chất làm sạch dịu nhẹ\"]','Cho sữa tắm ra bông tắm ướt, tạo bọt xốp và thoa đều khắp cơ thể, sau đó xả sạch lại bằng nước.','trangdiem-nuochoa/channel/sua-tam-nuoc-hoa/sua-tam1.webp'),(106,'Kem Che Khuyết Điểm Siêu Che Phủ 24H L\'Oréal Paris Infallible Full Wear 10ml',10,8,'Kem che khuyết điểm L\'Oréal Infallible Full Wear với đầu cọ siêu lớn Extra-Large Doe-Foot, chỉ 1 quẹt che phủ hoàn toàn quầng thâm mắt, vết thâm mụn, đốm nâu và sẹo rỗ suốt 24 giờ không xuống tông.','[\"Độ che phủ tuyệt đối Full-coverage che sạch quầng thâm và mụn đỏ\", \"Kháng nước, kháng mồ hôi và không trôi trượt trong thời tiết nóng ẩm\", \"Đầu cọ cỡ đại tán nhanh và đều trên mọi góc cạnh khuôn mặt\"]','[\"Bột màu khoáng siêu mịn\", \"Polyme khóa màu chống nước\", \"Vitamin E dưỡng ẩm\"]','Chấm một lượng nhỏ kem lên quầng thâm mắt hoặc vết thâm, dùng cọ hoặc mút dặm nhẹ nhàng cho tệp vào da.','trangdiem-nuochoa/l-oreal-paris/kem-lore/kem-che-khuyet-diem-l-oreal-paris-infallible-full-wear-10ml/lore-kem10.webp'),(107,'Kem Nền Che Phủ Bất Bại 32H Thoáng Khí L\'Oréal Paris Infallible 32H Fresh Wear 30ml',10,8,'Kem nền Infallible 32H Fresh Wear thế hệ mới của L\'Oréal với công nghệ Oxygen Technology siêu thoáng khí, vừa cho độ che phủ đỉnh cao vừa nhẹ tênh như không trang điểm, bền màu suốt 32 giờ.','[\"Độ che phủ cao bền bỉ 32 giờ mà da vẫn thoáng khí thở được\", \"Chống lem dính khẩu trang, chống thấm nước và kháng mồ hôi tối đa\", \"Bổ sung Vitamin C dưỡng sáng da và chỉ số chống nắng SPF 25 bảo vệ da\"]','[\"Công nghệ hạt màu siêu mịn\", \"Dẫn xuất Vitamin C\", \"Màng lọc SPF 25\"]','Bơm 1-2 giọt kem nền ra mu bàn tay, dùng cọ hoặc mút trang điểm tán đều từ trung tâm mặt ra xung quanh.','trangdiem-nuochoa/l-oreal-paris/kem-lore/kem-nen-che-phu-bat-bai-32h/lore-kem1.webp'),(108,'Kem Nền Dạng Serum Căng Mướt Tự Nhiên L\'Oréal Paris Infallible Tinted Serum 1% HA 30ml',10,8,'Sự kết hợp hoàn hảo giữa trang điểm và chăm sóc da: kem nền dạng serum L\'Oréal chứa 1% Hyaluronic Acid tinh khiết, vừa làm đều màu da mỏng nhẹ như sương vừa nuôi dưỡng làn da căng mọng ngậm nước.','[\"Lớp nền mỏng nhẹ tệp vào da như làn da thứ hai khỏe khoắn\", \"1% Hyaluronic Acid cấp ẩm sâu giúp da căng bóng sương mai cả ngày\", \"Các hạt khoáng sáng bắt sáng tự nhiên che mờ khuyết điểm li ti\"]','[\"1% Hyaluronic Acid tinh khiết\", \"Bột khoáng bắt sáng Luminous Pigments\"]','Lắc đều trước khi dùng. Nhỏ 2-3 giọt serum lên mặt và dùng ngón tay hoặc mút tán đều nhẹ nhàng.','trangdiem-nuochoa/l-oreal-paris/kem-lore/kem-nen-dang-serum-24h-cang-muot-tu-nhien-l-oreal-paris-infallible-24h-tinted-serum-1-hyaluronic-acid-30ml/lore-kem7.webp'),(109,'Kem Nền Mịn Nhẹ Tiệp Mọi Tông Da L\'Oréal Paris True Match Blendable Foundation 30ml',10,8,'Kem nền True Match biểu tượng của L\'Oréal với công nghệ vi hạt màu hòa hợp tiệp màu da 100%, bổ sung Hyaluronic Acid và Pro-Vitamin B5 dưỡng ẩm cho lớp nền rạng rỡ không tì vết.','[\"Tiệp màu da chuẩn xác, không tạo ngấn ranh giới giữa mặt và cổ\", \"Độ che phủ trung bình tự nhiên, làm mịn lỗ chân lông hoàn hảo\", \"Dưỡng ẩm 24h giữ cho làn da luôn mịn màng không bị mốc phấn\"]','[\"Hyaluronic Acid\", \"Glycerin\", \"Vitamin B5\", \"Hạt màu khoáng Micro-Match\"]','Chấm kem nền lên trán, má, cằm rồi dùng mút ẩm tán đều từ trong ra ngoài.','trangdiem-nuochoa/l-oreal-paris/kem-lore/kem-nen-lau-troi-dang-long-l-oreal-paris-true-match-blendable-foundation-30ml/lore-kem5.webp'),(110,'Kem Nền Mịn Nhẹ Lâu Trôi L\'Oréal Paris Infallible 24H Fresh Wear Foundation 30ml',10,8,'Dòng kem nền best-seller toàn cầu của L\'Oréal được các beauty blogger săn đón nhờ khả năng kiềm dầu tốt, chống nước và che phủ hoàn hảo các khuyết điểm mà vẫn giữ lớp nền tươi mới suốt 24h.','[\"Lớp finish satin mịn màng tự nhiên, kiềm dầu tốt\", \"Bền màu 24h không bị chảy nền hay đọng vệt khi đổ mồ hôi\", \"Phù hợp với mọi loại da, đặc biệt là da dầu và hỗn hợp\"]','[\"Oxygen Technology\", \"Bột thấm hút dầu vi hạt\", \"Vitamin E\"]','Tán đều kem nền lên mặt bằng bông mút hoặc cọ trang điểm.','trangdiem-nuochoa/l-oreal-paris/kem-lore/kem-nen-min-nhe-lau-troi-l-oreal-paris-infallible-24h-fresh-wear-liquid-foundation-30ml/lore-kem3.webp'),(111,'Kem Lót Dưỡng Ẩm Bắt Sáng Thần Thánh MAC Strobe Cream Pinklite 50ml',10,11,'Bảo bối của các chuyên gia trang điểm hậu trường sàn diễn: kem lót MAC Strobe Cream sắc hồng Pinklite chứa ngọc trai óng ánh và thảo mộc, biến làn da xỉn màu mệt mỏi trở nên bừng sáng rực rỡ dưới mọi ánh đèn.','[\"Tạo hiệu ứng da căng bóng ngậm nước rạng rỡ (Glass skin) tức thì\", \"Cấp ẩm tức thì và làm mềm bề mặt da cho lớp nền bám chặt\", \"Ánh nhũ ngọc trai hồng siêu mịn làm sáng bừng thần thái\"]','[\"Bột ngọc trai siêu mịn Pinklite\", \"Chiết xuất trà xanh chống oxy hóa\", \"Vitamin E & Bơ hạt mỡ\"]','Dùng làm kem lót trước khi đánh nền, hoặc trộn trực tiếp với kem nền, hoặc chấm lên xương gò má làm highlight bắt sáng.','trangdiem-nuochoa/mac/kem-mac/kem-lot-tao-hieu-ung-bat-sang-mac-strobe-cream-pinklite-50ml/mac-kem3.webp'),(112,'Kem Lót Nâng Tông Khử Vàng Da MAC Lightful C3 Naturally Luminous Primer SPF 50+ Tone Lavender 30ml',10,11,'Kem lót cao cấp MAC Lightful C3 sắc tím Lavender giúp trung hòa sắc vàng xỉn của làn da châu Á, nâng tông da trắng hồng trong veo chuẩn công chúa và chống nắng tối đa SPF 50+ PA++++.','[\"Triệt tiêu sắc tố vàng và sạm nám, nâng tông da trắng hồng trong suốt\", \"Chỉ số chống nắng cực cao SPF 50+ PA++++ bảo vệ da toàn diện\", \"Công nghệ C3 nuôi dưỡng da sáng khỏe từ sâu bên trong\"]','[\"Phức hợp Lightful C3 (Vitamin C, San hô, Hoa anh đào)\", \"Bột màu Lavender hiệu chỉnh quang học\"]','Thoa một lượng nhỏ lên toàn mặt sau bước dưỡng ẩm và trước bước kem nền.','trangdiem-nuochoa/mac/kem-mac/kem-lot-trang-diem-mac-glow-play-lightful-c3-tone-up-primer-spf-50-pa-tone-lavender-30ml/mac-kem1.webp'),(113,'Son Thỏi Mịn Lì Như Nhung MAC Powder Kiss Lipstick #908 Ready To Mingle - Màu Cam Nude',1,11,'Dòng son thỏi lì thế hệ mới MAC Powder Kiss đột phá với chất son mịn nhẹ tênh như nhung, màu #908 Ready To Mingle tông cam nude chuẩn Tây mang lại vẻ đẹp thời thượng, sang chảnh không đối thủ.','[\"Chất son lì đột phá lướt êm ái, làm mờ rãnh môi mượt mà\", \"Không gây khô môi, cảm giác nhẹ tênh như thoa một lớp bụi mịn\", \"Sắc son cam nude kiêu kỳ tôn lên thần thái sang trọng\"]','[\"Hạt bột màu phủ dưỡng chất\", \"Sáp vi tinh thể\", \"Chất làm mềm nhung mịn\"]','Thoa trực tiếp son lên môi từ tâm môi ra hai bên khóe môi. Dặm thêm lớp thứ 2 để tăng độ đậm đà.','trangdiem-nuochoa/mac/son-mac/son-mac-powder-kiss-hazy-matte-lipstick-908-ready-to-mingle-mau-cam-nude/mac-son5.webp'),(114,'Son Thỏi MAC MACximal Silky Matte Lipstick #607 Lady Danger - Màu Đỏ Cam 3.5g',1,11,'Phiên bản cải tiến MACximal với dung tích nhiều hơn, chứa bơ hạt mỡ và dầu dừa hữu cơ dưỡng ẩm suốt 8 giờ. Màu #607 Lady Danger đỏ cam san hô rực lửa làm bừng sáng mọi góc nhìn.','[\"Màu đỏ cam rực rỡ, quyền lực, cực kỳ tôn da và tôn nụ cười\", \"Chất son Silky Matte mới mượt mà gấp bội, không vón cục\", \"Dưỡng ẩm 8 giờ với dầu dừa và bơ hạt mỡ nguyên chất\"]','[\"Bơ hạt mỡ hữu cơ\", \"Bơ ca cao\", \"Dầu dừa tinh khiết\"]','Tô trực tiếp lên môi hoặc dùng cọ kẻ viền môi sắc nét.','trangdiem-nuochoa/mac/son-mac/son-mac-ximal-silky-matte-lip-607-lady-danger-mau-do-cam-3-5g/mac-son3.webp'),(115,'Son Thỏi MAC MACximal Silky Matte Lipstick #688 Go Retro - Màu Nâu Hồng Đào Cổ Điển 3.5g',1,11,'Màu son bán chạy hàng đầu MACximal #688 Go Retro pha trộn tinh tế giữa sắc hồng đào dịu dàng và ánh nâu đất cổ điển, mang lại vẻ đẹp thanh lịch, nàng thơ đậm chất quý cô Pháp.','[\"Sắc nâu hồng đào nhã nhặn, dùng đẹp hoàn hảo cả khi mặt mộc\", \"Bền màu lên tới 12 giờ, không lem trôi\", \"Mùi hương vani ngọt ngào đặc trưng của thương hiệu MAC\"]','[\"Chiết xuất bơ hạt mỡ\", \"Dầu dừa organic\", \"Sáp Candelilla\"]','Thoa lòng môi hoặc toàn bộ môi tùy sở thích trang điểm.','trangdiem-nuochoa/mac/son-mac/son-mac-ximal-silky-matte-lipstick-688-go-retro-mau-nau-hong-dao-3-5g/mac-son1.webp'),(116,'Kem Nền Kiềm Dầu Mịn Lì Quốc Dân Maybelline Fit Me Matte + Poreless 30ml',10,12,'Kem nền quốc dân Maybelline Fit Me Matte + Poreless chứa hạt đất sét khoáng siêu nhỏ hấp thụ bã nhờn, đem lại lớp nền mịn lì tự nhiên, se khít lỗ chân lông và kiềm dầu suốt cả ngày dài.','[\"Kiềm dầu vượt trội cho da dầu và hỗn hợp thiên dầu\", \"Thu nhỏ lỗ chân lông, làm mịn bề mặt da không tì vết\", \"Bảng màu đa dạng tiệp hoàn hảo mọi sắc độ da phụ nữ Việt\"]','[\"Bột đất sét khoáng hút dầu\", \"Hạt phấn siêu vi Micro-powders\"]','Chấm 5 điểm lên mặt, dùng mút ẩm hoặc cọ dặm đều từ trong ra ngoài.','trangdiem-nuochoa/maybelline/kem-nen-maybeline/kem-nen-dang-long-matte-poreless-liquid-foundation/maybelline-kem-nen3.webp'),(117,'Kem Nền Siêu Lâu Trôi Kháng Nước Maybelline Super Stay Active Wear 30H 30ml',10,12,'Kem nền siêu lì Maybelline Super Stay Active Wear 30H thách thức mồ hôi, nước và ma sát khẩu trang, cho lớp nền che phủ hoàn hảo suốt 30 giờ năng động mà không hề bí bách hay nặng mặt.','[\"Bền màu kỷ lục 30 giờ không trôi, không lem ra khẩu trang\", \"Che phủ hoàn toàn thâm mụn, tàn nhang và quầng thâm\", \"Công thức không dầu, không gây mụn trứng cá\"]','[\"Hạt màu bọc polyme kháng nước\", \"Bột khoáng kiềm dầu\"]','Tán nhanh kem nền lên từng vùng da mặt vì chất kem set lì khá nhanh.','trangdiem-nuochoa/maybelline/kem-nen-maybeline/kem-nen-lau-troi-super-stay-active-wear/maybelline-kem-nen1.webp'),(118,'Son Kem Lì Mịn Đệm Môi Maybelline Sensational Cushion Mattes 6.4ml',1,12,'Son kem đệm môi Maybelline Cushion Mattes với công nghệ hạt phấn nhung mịn Dimensional Matte, mang lại hiệu ứng môi dày dặn quyến rũ, nhẹ tênh và êm ái như gối đệm.','[\"Cảm giác trên môi êm ái, bồng bềnh như chạm vào đệm bông\", \"Bổ sung Vitamin E dưỡng môi mềm mượt, không làm lộ vân môi\", \"Lên màu chuẩn sắc ngay từ lần chạm cọ đầu tiên\"]','[\"Vitamin E dưỡng ẩm\", \"Hạt phấn nhung siêu mịn Dimensional Matte\"]','Thoa son từ giữa môi và tán đều nhẹ nhàng ra hai bên khóe môi.','trangdiem-nuochoa/maybelline/son-maybeline/son-kem-min-li-maybelline-sensational-cushion-mattes/maybelline-son5.webp'),(119,'Son Kem Bóng Siêu Lâu Trôi 16H Maybelline Super Stay Vinyl Ink 4.2ml',1,12,'Dòng son kem bóng gây bão mạng xã hội toàn cầu Maybelline Super Stay Vinyl Ink với công nghệ khóa màu Color Lock: bóng bẩy căng mọng như tráng gương nhưng khóa chặt màu suốt 16H không lem dính.','[\"Hiệu ứng môi bóng tráng gương căng mọng quyến rũ\", \"Bền màu 16 giờ, không lem trôi khi ăn uống hay đeo khẩu trang\", \"Chứa nha đam dưỡng môi mềm mịn không bị khô\"]','[\"Công nghệ khóa màu Color Lock\", \"Chiết xuất nha đam cấp ẩm\", \"Vitamin E\"]','LẮC ĐỀU THỎI SON TRONG 5 GIÂY trước khi dùng. Thoa lên môi và để khô tự nhiên trong 1-2 phút (không bặm môi trong lúc khô).','trangdiem-nuochoa/maybelline/son-maybeline/son-kem-vinyl-ink-longwear-liquid-lipcolor/maybelline-son3.webp'),(120,'Son Thỏi Mịn Lì Maybelline The Slim Matte Lipstick',1,12,'Son thỏi Maybelline The Slim với thiết kế thân son thanh mảnh và đầu vát vuông tinh tế, giúp kẻ viền môi sắc sảo đến từng milimet, chất son mịn lì nhẹ tênh tôn vinh vẻ đẹp hiện đại.','[\"Đầu vát góc cạnh viền môi chuẩn xác không cần chì kẻ môi\", \"Chất son lì mịn lướt êm ru, không gây bột hay khô ráp\", \"Màu sắc thời thượng, nhỏ gọn tiện lợi mang trong túi xách\"]','[\"Bơ hạt mỡ dưỡng ẩm\", \"Sáp ong tự nhiên\", \"Sắc tố màu đậm đặc\"]','Dùng cạnh son viền theo dáng môi, sau đó tô đầy son vào lòng môi.','trangdiem-nuochoa/maybelline/son-maybeline/son-li-slim-lipstick/maybelline-son1.webp'),(121,'Son Dưỡng Thạch Bóng Tan Chảy Romand Glasting Melting Balm #13 Scotch Nude 3.5g',1,15,'Son dưỡng thạch tan chảy Romand Glasting Melting Balm màu #13 Scotch Nude cam nâu đất ngọt ngào, tạo lớp màng nước bóng bẩy căng mọng như kẹo hồ lô và cấp ẩm dồi dào từ tinh dầu thực vật.','[\"Lớp màng nước bóng mọng tan chảy trên môi tạo hiệu ứng môi mọng nước\", \"Dưỡng ẩm chuyên sâu với dầu nụ tầm xuân, dầu hạt argan và bơ hạt mỡ\", \"Màu cam nâu nude tự nhiên, trong veo cực kỳ tôn da\"]','[\"Dầu nụ tầm xuân (Rosehip Oil)\", \"Dầu Argan\", \"Dầu hoa anh thảo\", \"Bơ hạt mỡ\"]','Vặn son lên khoảng 1-2mm thoa nhẹ nhàng lên môi. (Tránh vặn quá cao vì chất son mềm tan chảy).','trangdiem-nuochoa/romand/son-romand/son-duong-romand-glasting-melting-balm-13-scotch-nude/romand-son7.jpg'),(122,'Son Tint Nước Nhẹ Tựa Làn Sương Peripera Water Bare Tint #05 Red Update 3.7g',1,19,'Son tint nước Peripera Water Bare Tint màu #05 Red Update đỏ táo tươi tắn chứa 40% độ ẩm tự nhiên, lướt trên môi mát rượi và tệp chặt vào môi, tạo độ bóng trong veo và giữ màu ửng hồng cả ngày.','[\"Chứa 40% độ ẩm không gây khô môi, cảm giác nhẹ tênh như không bôi son\", \"Màu đỏ táo tươi tắn rạng rỡ, làm sáng bừng khuôn mặt mộc\", \"Lớp tint bám màu cực dai, không trôi loang lổ sau khi ăn uống\"]','[\"Phức hợp tinh dầu quả mơ\", \"Dầu hạt jojoba\", \"Nước khoáng tinh khiết\"]','Gạt cọ và tán đều vào lòng môi, dặm nhẹ thêm 1 lớp để tăng độ bóng và đậm màu.','trangdiem-nuochoa/romand/son-romand/son-tint-peripera-water-bare-tint-05-red-update/romand-son3.webp'),(123,'Son Tint Bóng Căng Mọng Trái Cây Romand Juicy Lasting Tint #20 Dark Coconut 5.5g',1,15,'Thỏi son tint bóng \"huyền thoại\" của Romand màu #20 Dark Coconut đỏ nâu dừa cực kỳ quyến rũ và tôn da, tạo lớp bóng kẹo ngọt dày dặn che phủ mọi vân môi mà không hề dính dớp.','[\"Màu đỏ nâu dừa hot-trend thời thượng, cực kỳ sáng da và trắng răng\", \"Độ bóng căng mọng như trái cây chín nước, tạo hiệu ứng môi đầy đặn\", \"Lớp tint màu bám cực lâu, để lại lớp base hồng đất tươi tắn sau khi ăn\"]','[\"Chiết xuất quả kiwi\", \"Chiết xuất đu đủ & bưởi\", \"Chất bóng ngậm nước\"]','Thoa son lên môi, đợi 1-2 phút cho lớp màng bóng thủy tinh nổi lên tự nhiên.','trangdiem-nuochoa/romand/son-romand/son-tint-romand-juicy-lasting-tint-20/romand-son10.jpg'),(124,'Son Tint Bóng Màu Nâu Nude Trái Hạt Romand Juicy Lasting Tint #23 Nucadamia 5.5g',1,15,'Màu #23 Nucadamia là sự hòa quyện hoàn mỹ giữa hạt mắc-ca và tông đỏ đất nhẹ nhàng, được mệnh danh là màu son MLBB (My Lips But Better) tự nhiên, thanh lịch đẹp nhất của Romand.','[\"Tông màu MLBB nâu đỏ hạt dẻ tự nhiên, đi học đi làm đều xinh xắn\", \"Tạo hiệu ứng đôi môi căng mọng như quả mọng vừa hái\", \"Mùi hương trái cây nhiệt đới ngọt ngào dễ chịu\"]','[\"Chiết xuất hạt macadamia\", \"Tinh dầu dừa cấp ẩm\", \"Vitamin E\"]','Tô một lớp mỏng khắp môi để có màu tự nhiên hàng ngày, hoặc tô 2 lớp để có đôi môi mọng nước kiêu sa.','trangdiem-nuochoa/romand/son-romand/son-tint-romand-juicy-lasting-tint-23/romand-son1.jpg'),(125,'Son Tint Bóng Trái Lê Chín Mọng Romand Juicy Lasting Tint #37 Mellow Pear 5.5g',1,15,'Nằm trong bộ sưu tập mới nhất của Romand, màu #37 Mellow Pear mang sắc hồng cam quả lê chín ngọt ngào và tươi mới, đánh thức vẻ trẻ trung tươi tắn trên gương mặt nàng.','[\"Sắc hồng cam đào nhẹ nhàng như quả lê mùa thu, trong trẻo tinh khôi\", \"Lớp màng bóng giữ ẩm sâu, không lo khô môi nứt nẻ\", \"Chất son mỏng nhẹ không bết dính môi\"]','[\"Chiết xuất quả lê tự nhiên\", \"Dưỡng chất cấp ẩm trái cây\", \"Bột màu tint siêu bền\"]','Thoa đều lên môi từ trong ra ngoài.','trangdiem-nuochoa/romand/son-romand/son-tint-romand-juicy-lasting-tint-37/romand-son5.jpg'),(126,'Combo Bộ 10 Mặt Nạ Giấy Dưỡng Da Toàn Diện Innisfree Squeeze Energy Mask Set',7,7,'Bộ sưu tập trọn bộ 10 mặt nạ giấy Innisfree Squeeze Energy Mask chiết xuất từ thiên nhiên đảo Jeju (Trà xanh, Nha đam, Rau má, Lựu đỏ, Diếp cá, Yến mạch,...), chăm sóc và nuôi dưỡng làn da toàn diện mỗi ngày trong tuần.','[\"Cung cấp đầy đủ các liệu trình dưỡng da: cấp ẩm, làm dịu, ngừa mụn và sáng da\", \"Chiết xuất từ thiên nhiên đảo Jeju thuần khiết, an toàn cho mọi loại da\", \"Món quà chăm sóc bản thân và người thân lý tưởng, tiết kiệm chi phí\"]','[\"Chiết xuất trà xanh, nha đam, rau má, lựu đỏ, diếp cá, yến mạch Jeju\"]','Sử dụng luân phiên các loại mặt nạ trong tuần. Đắp 15-20 phút sau bước làm sạch và toner.','chamsocda-anh/innisfree/mat-na/innisfree-mat-na.png'),(127,'Kem Chống Nắng La Roche-Posay Anthelios',1,1,'Kem chống nắng kiểm soát dầu hiệu quả suốt 12h.','Bảo vệ da phổ rộng, ngừa thâm nám','Nước khoáng, màng lọc XL-Protect','Thoa trước khi ra nắng 20 phút','https://example.com/laroche-thumb.jpg');
