-- DỮ LIỆU BẢNG: 15. ĐÁNH GIÁ SẢN PHẨM (REVIEWS)
-- ------------------------------------------------------
LOCK TABLES `reviews` WRITE;
/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (1,1,5,1,5,'Chất kem đặc mịn, bôi lên da ẩm mượt ngay lập tức, cực kỳ thích hợp cho da khô mùa lạnh hoặc ngồi máy lạnh nhiều. Sẽ tiếp tục ủng hộ shop!','2026-09-02 10:15:00'),(2,3,5,2,5,'Kem dưỡng phục hồi B5+ chân ái của mình mỗi khi nặn mụn xong. Giảm đỏ rát rất rõ rệt chỉ sau 1 đêm. 10/10!','2026-09-02 10:15:00'),(3,11,6,3,5,'Tẩy trang Bioderma hồng dùng siêu êm, làm sạch sâu bụi bẩn và kem chống nắng mà không hề bị khô căng rát mắt. Chai to dùng siêu tiết kiệm.','2026-09-03 14:20:00'),(4,80,6,4,5,'Mùi cà phê thơm nức mũi như đang ở quán cafe vậy, hạt scrub mịn không gây xước rát da, tắm xong da mềm mướt cực kỳ!','2026-09-03 14:20:00'),(5,18,7,5,4.5,'Hiệu quả đẩy mụn ẩn và kiềm dầu rất tốt. Lúc mới dùng hơi châm chích nhẹ nhưng sau 2 tuần da mịn màng hơn hẳn, mụn đầu đen ở cánh mũi giảm rõ rệt.','2026-09-05 09:00:00'),(6,2,7,6,5,'Sữa dưỡng ẩm CeraVe dùng rất nhẹ mặt, thấm nhanh không bị bết dính. Hàng chính hãng có tem phụ tiếng Việt đầy đủ.','2026-09-05 09:00:00'),(7,97,8,7,5,'Màu son lên môi cực xinh, mịn lì như nhung và không bị khô môi. Ăn uống nhẹ vẫn giữ được lớp base màu rất tự nhiên.','2026-09-08 16:30:00'),(8,95,8,8,4.5,'Phấn má 3CE màu tự nhiên, bám màu lâu tầm 6-7 tiếng, hộp nhỏ gọn dễ mang đi chơi.','2026-09-08 16:30:00');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

