INSERT INTO `blog_authors` VALUES ('dr_lan_anh','BS. CKII Nguyễn Lan Anh','Bác sĩ Chuyên khoa II Da liễu - Cố vấn Y khoa Hoàng Bảo','Hội đồng Da liễu Lâm sàng & Thẩm mỹ TP.HCM','https://images.unsplash.com/photo-1594824813629-87cfa77d0186?w=400&q=80&auto=format&fit=crop','Bác sĩ Lan Anh có hơn 14 năm kinh nghiệm công tác tại các bệnh viện da liễu tuyến đầu, chuyên nghiên cứu về sinh lý học màng lipid biểu bì và phục hồi da tổn thương sau can thiệp thẩm mỹ.'),('hoang_nam','Chuyên gia Hoàng Nam','Giám đốc Nghệ thuật & Chuyên gia Trang điểm Cao cấp','Ban Đào tạo Nghệ thuật Trang điểm Chuyên nghiệp','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80&auto=format&fit=crop','Từng tu nghiệp tại Paris và Seoul, Hoàng Nam sở hữu hơn 10 năm kinh nghiệm định hình phong cách trang điểm cho các tuần lễ thời trang và cố vấn sắc tố da cho người phụ nữ Á Đông.'),('mai_phuong','Nhà báo Mai Phương','Trưởng ban Biên tập Khoa học Làn da & Mỹ phẩm','Tạp chí Hoàng Bảo Beauty Journal','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400&q=80&auto=format&fit=crop','Tốt nghiệp cử nhân Hóa dược Đại học Quốc gia, Mai Phương đã có 9 năm theo đuổi mảng báo chí phân tích hoạt chất mỹ phẩm và phỏng vấn các chuyên gia đầu ngành trong và ngoài nước.');
/*!40000 ALTER TABLE `blog_authors` ENABLE KEYS */;
UNLOCK TABLES;

