LOCK TABLES `ingredient_guides` WRITE;
/*!40000 ALTER TABLE `ingredient_guides` DISABLE KEYS */;
INSERT INTO `ingredient_guides` VALUES (1,'AHA (Glycolic / Lactic Acid)','Alpha Hydroxy Acid','Tẩy tế bào chết bề mặt, kích thích tăng sinh chu kỳ biểu bì, làm sáng các vết thâm nắng và đốm nâu li ti.','Da sần sùi, da thô ráp, da khô mất nước, da có nếp nhăn li ti','Nên dùng buổi tối, bắt buộc bôi kem chống nắng SPF 50+ phổ rộng ban ngày.','Nồng độ 5% - 7% cho người mới bắt đầu'),(2,'BHA (Salicylic Acid)','Beta Hydroxy Acid (2-Hydroxybenzoic acid)','Tan trong dầu, thâm nhập sâu vào nang lông, hóa lỏng bã nhờn, tiêu sừng và diệt khuẩn mụn kỵ khí.','Da dầu nhờn, da mụn ẩn, mụn đầu đen, bít tắc nang lông, lỗ chân lông to','Bắt đầu từ nồng độ 1-2%, dùng 2-3 lần/tuần để tránh hiện tượng khô căng cục bộ.','Nồng độ 1% - 2% chuẩn da liễu'),(3,'Hyaluronic Acid (HA)','Sodium Hyaluronate đa phân tử','Ngậm nước gấp 1000 lần trọng lượng phân tử, giữ ẩm đa tầng từ màng đáy đến bề mặt, tạo độ căng bóng sinh học.','Mọi loại da, đặc biệt là da dầu thiếu nước, da khô rát, da sau điều trị laser','Thoa trên nền da còn ẩm để tránh hiện tượng thẩm thấu ngược (hút ẩm ngược từ da ra không khí).','Dùng hàng ngày 2 lần sáng & tối'),(4,'Niacinamide (Vitamin B3)','Nicotinamide / 3-Pyridinecarboxamide','Thu nhỏ lỗ chân lông, điều tiết bã nhờn, kích thích tổng hợp Ceramide tự thân, ức chế vận chuyển sắc tố Melanin.','Da dầu mụn, da thâm sau mụn, da xỉn màu, da tổn thương hàng rào lipid','Rất lành tính, hoạt động ở pH trung tính 6.0, kết hợp tốt với B5 và Peptides.','Nồng độ tối ưu 2% - 5%'),(5,'Retinol & Bakuchiol','Vitamin A derivative & Phyto-Retinol','Tăng sinh Collagen type I và III, làm mờ nếp nhăn sâu, tăng tốc chu kỳ thay mới tế bào, ngăn ngừa lão hóa sớm.','Da bắt đầu lão hóa từ tuổi 22+, da có đốm đồi mồi, da dày sừng','Cần cấp ẩm kỹ bằng B5/Ceramide, bắt đầu từ nồng độ thấp đến cao, dùng cách ngày.','Nồng độ khởi đầu 0.1% - 0.3%'),(6,'Centella Asiatica & B5','Madecassoside & D-Panthenol','Làm dịu phản ứng viêm cấp tính, hạ nhiệt làn da bỏng rát, sửa chữa cấu trúc mô liên kết và phục hồi mao mạch.','Da nhạy cảm, da sau peel, da tổn thương do kem trộn hoặc corticoid','Có thể thoa dặm nhiều lần trong ngày khi thấy da bị căng rát, không gây bí bách nang lông.','Dùng tự do theo nhu cầu phục hồi'),(7,'AHA (Glycolic / Lactic Acid)','Alpha Hydroxy Acid','Tẩy tế bào chết bề mặt, kích thích tăng sinh chu kỳ biểu bì, làm sáng các vết thâm nắng và đốm nâu li ti.','Da sần sùi, da thô ráp, da khô mất nước, da có nếp nhăn li ti','Nên dùng buổi tối, bắt buộc bôi kem chống nắng SPF 50+ phổ rộng ban ngày.','Nồng độ 5% - 7% cho người mới bắt đầu'),(8,'BHA (Salicylic Acid)','Beta Hydroxy Acid (2-Hydroxybenzoic acid)','Tan trong dầu, thâm nhập sâu vào nang lông, hóa lỏng bã nhờn, tiêu sừng và diệt khuẩn mụn kỵ khí.','Da dầu nhờn, da mụn ẩn, mụn đầu đen, bít tắc nang lông, lỗ chân lông to','Bắt đầu từ nồng độ 1-2%, dùng 2-3 lần/tuần để tránh hiện tượng khô căng cục bộ.','Nồng độ 1% - 2% chuẩn da liễu'),(9,'Hyaluronic Acid (HA)','Sodium Hyaluronate đa phân tử','Ngậm nước gấp 1000 lần trọng lượng phân tử, giữ ẩm đa tầng từ màng đáy đến bề mặt, tạo độ căng bóng sinh học.','Mọi loại da, đặc biệt là da dầu thiếu nước, da khô rát, da sau điều trị laser','Thoa trên nền da còn ẩm để tránh hiện tượng thẩm thấu ngược (hút ẩm ngược từ da ra không khí).','Dùng hàng ngày 2 lần sáng & tối'),(10,'Niacinamide (Vitamin B3)','Nicotinamide / 3-Pyridinecarboxamide','Thu nhỏ lỗ chân lông, điều tiết bã nhờn, kích thích tổng hợp Ceramide tự thân, ức chế vận chuyển sắc tố Melanin.','Da dầu mụn, da thâm sau mụn, da xỉn màu, da tổn thương hàng rào lipid','Rất lành tính, hoạt động ở pH trung tính 6.0, kết hợp tốt với B5 và Peptides.','Nồng độ tối ưu 2% - 5%'),(11,'Retinol & Bakuchiol','Vitamin A derivative & Phyto-Retinol','Tăng sinh Collagen type I và III, làm mờ nếp nhăn sâu, tăng tốc chu kỳ thay mới tế bào, ngăn ngừa lão hóa sớm.','Da bắt đầu lão hóa từ tuổi 22+, da có đốm đồi mồi, da dày sừng','Cần cấp ẩm kỹ bằng B5/Ceramide, bắt đầu từ nồng độ thấp đến cao, dùng cách ngày.','Nồng độ khởi đầu 0.1% - 0.3%'),(12,'Centella Asiatica & B5','Madecassoside & D-Panthenol','Làm dịu phản ứng viêm cấp tính, hạ nhiệt làn da bỏng rát, sửa chữa cấu trúc mô liên kết và phục hồi mao mạch.','Da nhạy cảm, da sau peel, da tổn thương do kem trộn hoặc corticoid','Có thể thoa dặm nhiều lần trong ngày khi thấy da bị căng rát, không gây bí bách nang lông.','Dùng tự do theo nhu cầu phục hồi');
